
import React from 'react';
import DataTable from "../../../tables/DataTable";


export default function InvoiceList(props) {
  const state = {
    title: 'Invoices',
    dataSource: 'invoices',
    actionUrl: 'invoice',
    keys: ["dateCreated", "organisationName", 'number', 'description', 'amount', "dueDate"],
    titles: ["Invoice Date", "Organisation Name", 'number', 'description', 'amount', "Due Date"],
    numberFields: [],
    dateFields: [],
    displayActions: true,
    addStatus: 11,
    dueDate: true,
    filterObj: [],
  };

  const {
    title,
    keys,
    actionUrl,
    dataSource,
    titles,
    dateFields,
    numberFields,
    displayActions,
    addStatus,
    dueDate,
    orgCode,
    filterObj
  } = state;
  return (
    <>
      <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                 dataSource={dataSource} dateFields={dateFields} titles={titles}
                 addStatus={addStatus}
                 dueDate={dueDate}
                 displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                 sortKey={"status"} sortValue={1}
      />
    </>
  )
}
