import React, {useRef} from 'react';
import DataTable from "../../../tables/DataTable";

class OrgTable extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      title: 'Organisations',
      dataSource: 'organisations',
      actionUrl: 'organisation',
      keys: ['dateCreated', 'organisationCode', 'name', 'physicalAddress', 'description', "organisationClass"],
      titles: ['Created on', 'Code', 'name', 'physicalAddress', 'Line of Business', "organisationClass"],
      numberFields: [],
      dateFields: [],
      displayActions: true,
      filterObj: props.filterObj,
    };
    this.child = React.createRef();
  }

  performReload= (filterObj) => {
    this.child.current.updateDataTable(filterObj)
  }

  render() {
    const {
      title,
      keys,
      actionUrl,
      dataSource,
      titles,
      dateFields,
      numberFields,
      displayActions,
      orgCode,
      filterObj
    } = this.state;

    return (
      <>
        <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                   dataSource={dataSource} dateFields={dateFields} titles={titles}
                   displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                   ref = {this.child} addStatus={11}
        />
      </>
    );
  }

}

const OrgList = React.forwardRef((props, ref) => (
  <OrgTable filterObj={props.filterObj}  ref={ref} />
));

export default OrgList;
