import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import {toast} from "react-toastify";
import apiStore from "../../../api/apiStore";

const initialState = {
    status: 'idle',
}


export const getOrganisations = createAsyncThunk(
    'organisation/organisationSlice',
    async (data,{rejectWithValue}) => {
        try {
            const response = await apiStore.post('organisations', data)
            return response.data;
        } catch (err) {
            return rejectWithValue(err.response.data)
        }
    }
)

const organisationSlice = createSlice({
    name: 'organisations',
    initialState,
    reducers: {
    },
    extraReducers:(builder)=> {
        builder.addCase(getOrganisations.pending,(state,action)=>{
            state.status='loading'
        });
        builder.addCase(getOrganisations.fulfilled, (state, action) => {
            if (action.payload.status==='SUCCESS'){
                localStorage.setItem("AuthToken", action.payload.token)
                state.status='success'
            }
            if(action.payload.status==='FAILED'){
                state.status='failed'
                toast.info(`${action.payload.message}`)
            }
        });
        builder.addCase(getOrganisations.rejected, (state, action) => {
            state.status = 'rejected'
        });
    }
})
export const {} = organisationSlice.actions
export default organisationSlice.reducer

