import React, {useState, useEffect, useRef, createRef} from 'react';
import Breadcrumb from './Breadcrumb';
import OrgList from "./OrgList";
import {useForm, useWatch} from "react-hook-form";
import {Col, Modal, Row} from 'react-bootstrap'
import * as yup from "yup";
import {Services} from "../../../../Services";
import swal from "sweetalert";

const Content = () => {
  const [show, setShow] = useState(false)

  const services = new Services(this);
  const onshowModal = () => setShow(true);
  const onHideModal = () => setShow(false);
  const {register, handleSubmit} = useForm();
  const {register: record, handleSubmit: handleSub, control,reset} = useForm();
  /*const classFilter = useWatch({
    control,
    name: "organisationClass"
  })
  const statusFilter = useWatch({
    control,
    name: "status"
  })*/
  const [filterObj, setFilterObj] = useState([]);
  /*
  useEffect(() => {
    let filters = [{}];
    filters[0].organisationClass = classFilter ? classFilter : "";
    filters[0].status = statusFilter ? statusFilter : "";
    setFilterObj(filters);
  }, [classFilter, statusFilter])*/
  const schemaResolver = yup.object().shape({
    name: yup.string().required(),
    email: yup.string().required(),
    phone: yup.string().required(),
    location: yup.string().required(),
    address: yup.string().required(),
    adminName: yup.string().required(),
    defaultPassword: yup.string().required(),

  })
  const child = useRef();

  const onSubmit = (values) => {
    swal({
      title: "Add Organisation?",
      text: "Make sure all the data you filled in is correct",
      icon: "info",
      //@ts-ignore
      buttons: true,
      dangerMode: true,
    })
      .then((willDelete) => {
        if (willDelete) {
          values["status"] = "ACTIVE";
          services.addItem('organisation', values).then(() => {
            swal("Organisation added Successfully", {
              icon: 'success',
            }).then(() => '')
          })
        } else {
          swal("Organisation not added", {
            icon: "info",
          }).then(() => '');
        }
      });
    onHideModal();

  }
  const jss = {
    button: {
      display: 'flex',
      justifyContent: 'flex-end'
    }
  }
  const sleep = (time) => {
    return new Promise((resolve) => setTimeout(resolve, time));
  }
  const [tier, setTier] = useState("")
  const tierChanged = (e) => {
    let obj = JSON.parse(JSON.stringify(filterObj))
    let found = false;
    obj.forEach((item, index)=>{
      if(item.key==="organisationClass"){
        obj[index].value = e.target.value;
        found = true
      }
    })
    if(!found){
      obj.push({key:"organisationClass", value: e.target.value})
    }
    setTier(e.target.value)
    setFilterObj(obj)
    child.current.performReload(obj)
  }
  const [status, setStatus] = useState("")
  const statusChanged = (e) => {
    let obj = JSON.parse(JSON.stringify(filterObj))
    let found = false;
    obj.forEach((item, index)=>{
      if(item.key==="status"){
        obj[index].value = e.target.value;
        found = true
      }
    })
    if(!found){
      obj.push({key:"status", value: e.target.value})
    }
    setTier(e.target.value)
    setFilterObj(obj)
    child.current.performReload(obj)
  }
  const resetFilters=()=>{

    setFilterObj((prevState) => ([]));
    reset();
    child.current.performReload([])
  }
  return (
    <div className="ms-content-wrapper">
      <div className="row">
        <Breadcrumb/>
      </div>
      <div className={`row`} style={{alignItems: "center", paddingLeft: "20px"}}>

        <form className={"w-75"} style={{display: "flex", flexFlow: "row nowrap",}}>
          <select defaultValue={""} {...record("organisationClass")}
                  className={"form-control w-25 mb-3 mr-3 selectFilter"} id={"organisationClass"}
            {...record("organisationClass", {onChange: (e) => tierChanged(e)})}     >
            <option value={""}>Filter by Organisation Class</option>
            <option value={"TIER 1"}>TIER 1</option>
            <option value={"TIER 2"}>TIER 2</option>
            <option value={"TIER 3"}>TIER 3</option>

          </select>
          <select {...record("status", {onChange: (e) => statusChanged(e)})}
            className={"form-control w-25 mb-3 selectFilter"}
                  id={"status"}>
            <option value={""}>Filter by Status</option>
            <option value={"ACTIVE"}>ACTIVE</option>
            <option value={"INACTIVE"}>INACTIVE</option>
          </select>
        </form>

        <button style={{margin: '10px 15px 20px auto'}} onClick={resetFilters} className={`btn btn-primary float-right`}>
           Clear Filters
        </button>

        <button style={{margin: '10px 15px 20px auto'}} onClick={onshowModal} className={`btn btn-primary float-right`}>
          <i className={`fa fa-plus`}/> Add Organisation
        </button>
      </div>
      <OrgList filterObj={filterObj} that={this} ref={child}/>     Memory: 1.5M

      <Modal show={show} onHide={onHideModal} aria-labelledby="contained-modal-title-center" size="lg" centered>
        <Modal.Header onHide={onHideModal} closeButton>
          <Modal.Title className="m-0">Add New Organisation</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <form onSubmit={handleSubmit(onSubmit)} resolver={schemaResolver}>
            <Row>
              <Col md={6}>
                <div className="form-group">
                  <label htmlFor="name">Org. Name</label>
                  <input type="text"  {...register("name")} className="form-control" id="name"
                         placeholder="Enter Org. Name"/>
                </div>
                <div className="form-group">
                  <label htmlFor="organisationClass">Org. Tier</label>
                  <select {...register("organisationClass")} className="form-control" id="organisationClass">
                    <option value={``} selected disabled hidden>Select Organisation Class</option>
                    <option value={`TIER 1`}>TIER 1</option>
                    <option value={`TIER 2`}>TIER 2</option>
                    <option value={`TIER 2`}>TIER 3</option>
                  </select>
                </div>
                <div className="form-group">
                  <label htmlFor="email">Email</label>
                  <input type="text"  {...register("email")} className="form-control" id="email"
                         placeholder="Enter Email address"/>
                </div>
                <div className="form-group">
                  <label htmlFor="description">Line of Business</label>
                  <textarea type="text"  {...register("description")} className="form-control" id="description"
                            placeholder="Enter Short Organisation Bio"/>
                </div>
                <div className="form-group">
                  <label htmlFor="phone">Phone</label>
                  <input type="text"  {...register("phone")} className="form-control" id="phone"
                         placeholder="Enter phone number"/>
                </div>

              </Col>
              <Col md={6}>
                <div className="form-group">
                  <label htmlFor="location">Location</label>
                  <input type="text"  {...register("location")} className="form-control" id="location"
                         placeholder="Enter Location"/>
                </div>
                <div className="form-group">
                  <label htmlFor="address">Address</label>
                  <input type="text"  {...register("address")} className="form-control" id="address"
                         placeholder="Enter address"/>
                </div>
                <div className="form-group">
                  <label htmlFor="adminName">Admin Name</label>
                  <input type="text"  {...register("adminName")} className="form-control" id="adminName"
                         placeholder="Enter Admin User Name"/>
                </div>
                <div className="form-group">
                  <label htmlFor="defaultPassword">Set default Password</label>
                  <input type="password"  {...register("defaultPassword")} className="form-control" id="defaultPassword"
                         placeholder="Enter Password"/>
                </div>
              </Col>
            </Row>


            <div style={jss.button}>
              <button type={`submit`} onClick={() => onHideModal} style={{
                margin: '10px 15px 30px auto',
              }} className={`btn btn-primary`}>
                <i className={`fa fa-plus`}/><span style={{color: '#fff', fontWeight: 600}}> Add Organisation</span>
              </button>

            </div>
          </form>
        </Modal.Body>

      </Modal>
    </div>
  );
}

export default Content;
