
    import React from 'react';
    import DataTable from "../../../tables/DataTable";


    export default function OrdersList(props) {
    const state = {
        title: 'Orders',
        dataSource: 'orders',
        actionUrl: 'order',
        keys: ['dateCreated',"organisationName",'lpoNumber','orderedBy','deliveryLocation'],
        titles: ['Date Created',"Organisation Name",'Order Number','Ordered By','delivery Location'],
        numberFields: [],
        dateFields: [],
        displayActions: true,
        addStatus:10,
        filterObj: [],
    };

    const {title, keys, actionUrl, dataSource, titles, dateFields, numberFields,displayActions,addStatus,orgCode,filterObj} = state;
    return (
            <>
                <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                                   dataSource={dataSource} dateFields={dateFields} titles={titles}
                                   displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                           addStatus={addStatus}
                />
            </>
    )

}
