import React, {Fragment, useEffect} from "react";
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Link} from "react-router-dom";
import {Button, Card, Col, Row} from "react-bootstrap";
import {Services} from "../../../../Services";
import userAvt from '../../../../assets/img/avt.svg'
import moment from "moment";
import swal from'sweetalert'


export default class ViewUser extends React.Component {

    constructor(props) {
        super(props);
        this.state = {
            row: props.match.params.id,
            user:{},


        };
        this.services= new Services(this);

    }

    getUser=()=>{
        this.services.getItem('application-user',`${this.state.row}`).then((resp)=>{
            this.setState({user:resp.data});
        })
    }
    handleDeactivateUser=()=>{
        swal({
          title:`${this.state.user.status==="ACTIVE"?"Deactivate User":"Activate User"}`,
          text:`${this.state.user.status==="ACTIVE"?"Users can be activated later":"Users can be deactivated later"}`,
          icon:"warning",
          buttons:{
            ok:`${this.state.user.status==="ACTIVE"?"Deactivate":"Activate"}`,
            cancel:"Cancel",
          }
        }).then((willDeactivate)=>{
          if (willDeactivate){
            const{user}=this.state;
            let inActiveUser=user;
            if(user.status==="ACTIVE"){
              inActiveUser.status="INACTIVE"
            }else{
              inActiveUser.status="ACTIVE"
            }
            this.services.editItem("/application-user",inActiveUser)
              .then((resp)=>{
                swal({
                  icon:"success",
                  text:"User Status Successfully changed"
                })
              }).catch((err)=>{
              console.warn(err)
            })
          }
        })
    }
    componentDidMount() {
        this.getUser();
    }

    render() {
        const {user}=this.state;
        return (
            <Fragment>
                <MetaTags>
                    <title>Taam | Users</title>
                    <meta
                        name="description"
                        content="#"
                    />
                </MetaTags>
                <div className="body ms-body ms-aside-left-open ms-primary-theme" id="body">
                    {/*<Setting />*/}
                    <Sidenav/>
                    {/*<Recentactivity/>*/}
                    <main className="body-content">
                        <Navbar/>
                        <div className="ms-content-wrapper">
                            <div className="row">
                                <div className="col-md-12">
                                    <nav aria-label="breadcrumb">
                                        <ol className="breadcrumb pl-0">
                                            <li className="breadcrumb-item"><Link to="/"><i
                                                className="bx bxs-home"/> Home</Link></li>
                                            <li className="breadcrumb-item" aria-current="page"><Link to='/users'> <i
                                                className="fa fa-shopping-basket"/>Users</Link></li>
                                            <li className="breadcrumb-item active"
                                                aria-current="page">{user.code}</li>
                                        </ol>
                                    </nav>
                                </div>
                            </div>
                            <div>
                                <Row>
                                    <Card style={{
                                        width:800
                                    }}>
                                        <Card.Body>
                                            <Row className="">
                                                <Col md={4}>
                                                    <img
                                                        style={{
                                                            borderRadius:'250px',
                                                            objectFit:'cover',
                                                        }}
                                                        src={user.imageUrl?user.imageUrl:userAvt}
                                                        alt="" />
                                                </Col>
                                                <Col className="w-100">
                                                    <Row>
                                                       <Col style={{
                                                           padding:'40px 20px 0'
                                                       }} >
                                                           <h4 className="mt-0 mb-1">{user.name}</h4>

                                                           <p className="text-muted">
                                                               <i className='bx bxs-user'></i> Role: {user.role}
                                                           </p>
                                                       </Col>
                                                    </Row>

                                                   <Row>
                                                           <button className={`btn btn-xs m-2 ${user.status==="ACTIVE"? 'btn-success'
                                                               :'btn-light'} me-1`}>
                                                               {user.status==="ACTIVE"? user.status : 'NOT ACTIVE'}
                                                           </button>
                                                           <a href={`tel:${user.phone}`} className="btn m-2 btn-xs btn-secondary">
                                                               <i className={`bx bxs-phone`}/> Call
                                                           </a>
                                                     <button className={`btn m-2 ${user.status==="ACTIVE"?"btn-warning":"btn-info"}`} onClick={()=>this.handleDeactivateUser()}>
                                                       {user.status==="ACTIVE"?"Deactivate user":"Activate User"}
                                                     </button>
                                                   </Row>
                                                </Col>
                                            </Row>

                                            <p className="mb-3 mt-4 text-uppercase text-light bg-gradient-light p-2">
                                                <i className="bx bxs-user-circle"></i> Personal Information
                                            </p>

                                            <div>
                                                <p className="font-13 text-muted">
                                                    <i className={`fa fa-feather-alt`}/> About Me :
                                                <span className="mb-3"><b className={`text-dark`}>{user.about}</b> </span></p>

                                                <p className="font-13 text-muted mb-1">
                                                    <i className={`fa fa-user`}/> Role :
                                                <span className="mb-3"><b className={`text-dark`}>{user.role}</b> </span></p>

                                                <p className="font-13 text-muted mb-1">
                                                    <i className={`fa fa-calendar`}/> Added :
                                                <span className="mb-3"><b className={`text-dark`}>{moment(user.dateCreated).format('MMMM DD YYYY')}</b> </span></p>

                                                <p className="font-13 text-muted mb-1">
                                                    <i className={`fa fa-envelope`}/> Email :
                                                <span className="mb-0"><b className={`text-dark`}> {user.email}</b></span></p>
                                                <p className="font-13 text-muted mb-1">
                                                    <i className={`fa fa-phone`}/> Phone :
                                                <span className="mb-0"><b className={`text-dark`}>{user.phoneNumber}</b> </span></p>
                                            </div>
                                        </Card.Body>
                                    </Card>
                                </Row>
                            </div>
                        </div>
                    </main>
                    {/*<Quickbar/>*/}
                </div>
            </Fragment>
        )
    }



}
