import React, {Component, useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import InvoiceList from "./InvoiceList";
import {Services} from "../../../../Services";
import {useForm, useWatch} from 'react-hook-form';
import * as yup from "yup";
import swal from "sweetalert";
import {Alert, Form, Modal, Row} from "react-bootstrap";
import Select2 from 'select2';
import {AutoComplete, Select} from "antd";
const { Option } = Select;


const Content =()=>{

    const[show,setShow]=useState(false);
    const [showNext,setShowNext]=useState(false);
    const [invNo, setInvNo]=useState('');
    const [totalAmount, setTotalAmount]=useState(0);
    const [org, setOrg]=useState('');
    const [selectedDelivery, setSelectedDelivery]=useState({});
    const [selectedOrg, setSelectedOrg]=useState({});
    const [selectedDeliveries, setSelectedDeliveries]=useState([]);
    const [organisations, setOrganisations]=useState([]);
    const [deliveries, setDeliveries]=useState([]);
    const {register,control,handleSubmit} = useForm();
    const [selected,setSelected]=useState([])
    const [submitted,setSubmitted]=useState('')

    const [products,setProducts]=useState([]);
    const [organisationCode,setOrganisationCode]=useState("");
    const clearState=()=>{
        setInvNo('')
        setOrg('')
        setSelectedDelivery({})
        setOrganisations([])
        setDeliveries([])
    }


    const {register:register2,handleSubmit:handleSubmit2} = useForm();
    const services = new Services(this);
    const onshowModal=()=>setShow(true);
    const onHideModal=()=>setShow(false);


    const total=(array)=>{
      let totalAmount=0;
      array.map((item)=>{
        totalAmount+=item.totalAmount;
      })
      return totalAmount;
    }


    const onSubmit=(values)=>{
      values.status = 'PENDING';
      values.number=invNo;
      values.amount=total(products);
      values.organisationName=selectedOrg.name;
      values.organisationCode=selectedOrg.code;

        services.addItem('invoice',values)
          .then((res)=>{
            onSubmitNext(res.data.serviceReturnValue,selectedOrg.name);


        }).catch((err)=>console.warn(err))
        onHideModal();

    }
  const [options, setOptions] = useState([]);
    const searchRes=async(organisationSelect)=>{
      try {
        let orgs=[];
        (organisationSelect.data.data||[]).map(item=>{
          item.value=item.name;
          item.label=item.name;
          orgs.push(item);
        })
        return orgs
      }catch(err) {
        console.log(err)
      }
    }
    const onSearch = async (searchText) => {
      const searchOrganisations= await services.getPaginated("organisations",searchText,0,[]);
      const namesArr=await searchRes(searchOrganisations);
      try {
        setOptions(namesArr);
      }catch(err){
        console.log(err);
      }
    };

  const onSelect = (selectedName) => {
    for (let i = 0; i< options.length; i++){
      let o = options[i];
      if(o.name===selectedName) {
        setSelectedOrg(o);
        setOrganisationCode(o.code);
        console.log(o, selectedName)
      }
    }
  };
    const onSubmitNext=(d,e)=>{
      products.map((item)=>{
        item.invoiceCode=d;
        item.organisationName=e;
        services.addItem('invoice-item',item)
          .then((res)=>{
            swal({
              icon:'success',
              title:"Invoice Added Successfully",
              text:'Check to confirm that all your invoice items have been added.'
            }).then(()=>'')
          }).catch((err)=>{
          console.warn(err);
        })
      })
    }

    useEffect(()=>{
        services.getPaginated('organisations', '', 0, []).then((resp) =>{
            setOrganisations(resp.data.data);
        }).catch((err)=>{
            console.warn(err)
        })
    },[])

    useEffect(()=>{
      services.getPaginated('deliveries', '', 0, [{
        "key": "organisationCode",
        "value": organisationCode,
      },{
        "key": "section",
        "value": "UNDELIVERED",
      }]).then((resp) => {
        setDeliveries(resp.data.data);
        setInvNo(`INV${createID(7)}`)
      }).catch((err) => {
        console.warn(err)
      })
    },[organisationCode])
  useEffect(()=>{
    selected.forEach(function(sel){
      let prods=[];
      deliveries.map((item,index)=>{
       if (item.code===sel&&item.organisationCode===organisationCode){
         let product={};
         product.invoiceCode=invNo;
         product.deliveryCode=item.code;
         product.description=item.productDescription;
         product.quantity=item.quantity;
         product.unitPrice=item.unitPrice;
         product.totalAmount=item.quantity*item.unitPrice;
         product.organisationCode=organisationCode;
         product.name=item.productName+" to "+item.location;
         prods.push(product);
         products[products.length]=product;
         setProducts(products);
       }
      })

    });

  },[submitted])

    const handleChange=(values)=> {
      setSelected(values);
    }
    const jss={
        button:{
            display:'flex',
            justifyContent:'flex-end'
        }
    }
    const sleep = (time) => {
        return new Promise((resolve) => setTimeout(resolve, time));
    }
    const createID=(x)=>{
        return (Math.random() + 1).toString(36).substring(x).toUpperCase();
    }


    return (
        <div className="ms-content-wrapper">
            <div className="row">
                <Breadcrumb/>
            </div>
            <div className={`row`}>
                <button style={{margin:'10px 15px 20px auto'}} onClick={onshowModal} className={`btn btn-primary`}>
                    <i className={`fa fa-plus`}/> Send Invoice
                </button>
            </div>
            <InvoiceList/>
            <Modal centered show={show} onHide={onHideModal} aria-labelledby="contained-modal-title-vcenter"  >
                <Modal.Header onHide={onHideModal} closeButton>
                    <Modal.Title className="m-0">Send Invoice</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <form id='modal1' onSubmit={handleSubmit(onSubmit)} >
                        <div className="form-group">
                            <label htmlFor="organisationCode">Organisation</label>
                          <AutoComplete
                            options={options}
                            style={{ width: 200 }}
                            onSelect={onSelect}
                            onSearch={onSearch}
                            className="b-block w-100"
                            id="organisationCode"
                            placeholder="search organisation"
                          />

                        </div>

                      <div className="form-group">
                        <label htmlFor="delivery">Delivery</label>
                        <Select
                          mode="multiple"
                          allowClear
                          style={{ width: '100%' }}
                          onChange={handleChange}
                          placeholder="Please select"
                          >
                          {deliveries.map((item,index)=>
                            <Select.Option key={index} value={item.code}>{item.location} - {item.productName}</Select.Option>
                          )}
                        </Select>
                      </div>
                        <div className="form-group">
                            <label htmlFor="dueDate">Due Date</label>
                            <input type="date"   {...register('dueDate')} className="form-control" id="dueDate" placeholder="Enter Short description"/>
                        </div>
                      <div className="form-group">
                            <label htmlFor="description">Description</label>
                            <textarea type="text"   {...register('description')} className="form-control" id="description" placeholder="Enter Short description"/>
                        </div>

                        <div style={jss.button} >
                            <button type={`submit`} onClick={()=>{
                              setSubmitted("submit");
                              onHideModal()}} style={{
                                margin:'10px 15px 30px auto',
                            }} className={`btn btn-primary`}>
                                <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}> Send Invoice</span>
                            </button>
                        </div>
                    </form>
                </Modal.Body>

            </Modal>

        </div>
    );

}

export default Content;
