import React, {useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import DeliveriesList from "./DeliveriesList";
import {Button, Modal, Row} from 'react-bootstrap';
import {useForm} from "react-hook-form";
import {Services} from "../../../../Services";
import swal from "sweetalert";
import CreateDelivery from "./CreateDelivery";

const Content =()=>{
    const [show,setShow]=useState(false);
    const [products,setProducts]=useState([]);
    const [orgs,setOrgs]=useState([]);
    const onShow=()=>setShow(true);
    const onHide=()=>setShow(false);
    const services=new Services(this);
    useEffect(()=>{
        services.getPaginated("products", '', 0, []).then((res)=>{
            setProducts(res.data.data)
        }).catch((err)=>{
            console.warn(err)
        })
        services.getPaginated("organisations", '', 0, []).then((res)=>{
              setOrgs(res.data.data)
          }).catch((err)=>{
              console.warn(err)
          })
    }, [])

    return (
        <div className="ms-content-wrapper">
            <div className="row">
                <Breadcrumb/>
            </div>
            <Row style={{textAlign:'right',padding:'15px'}}>
                <Button variant={`success`} onClick={onShow}>
                    <i className={`fa fa-plus`}/> Create Delivery
                </Button>
            </Row>
            <DeliveriesList/>
            <CreateDelivery
              show={show}
              onHide={onHide}
              products={products}
              org={orgs}
            />
        </div>
    );

}

export default Content;
