import React, {Fragment, useEffect} from "react";
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Tabs} from "antd";
import {Link} from "react-router-dom";
import Barcode from 'react-barcode';
import 'antd/dist/antd.css';
import swal from "sweetalert";

import 'bootstrap/dist/css/bootstrap.min.css';
import {Services} from "../../../../Services";
import {Card, Col, Row} from "react-bootstrap";
import moment from "moment";
import Button from "react-bootstrap/Button";

export default class ViewOrg extends React.Component{

    constructor(props) {
        super(props);
        this.state={
            paymentId:props.match.params.id,
            payment:{}
        }
        this.services=new Services(this)
    }
    getPayment(){
        this.services.getItem('payment',`${this.state.paymentId}`)
            .then((resp)=>{
                this.setState({payment:resp.data})
            }).catch((err)=>{
                console.warn(err)
        })
    }
    handleConfirmPayment(id){
        swal({
            title: "Confirm Payment?",
            text: "Proceed to Mark Payment Paid",
            icon: "info",
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(`${id}`,"PAID","PAYMENT").then((res)=>{
                        swal("Payment Marked as Paid ", {
                            icon: "success",
                            title:res.data.status
                        }).then(()=> '');
                        let x=this.state.payment
                        x.confirmedBy=localStorage.getItem('name');
                        x.status='PAID';

                        this.services.editItem('payment',x).then((resp)=>{
                        })
                    })

                } else {
                    swal.close()
                }
            });
    }
    componentDidMount() {
        this.getPayment();
    }
    render() {
        const {payment}=this.state;
        return (
            <Fragment>
                <MetaTags>
                    <title>Taam | Users</title>
                    <meta
                        name="description"
                        content="#"
                    />
                </MetaTags>
                <div className="body ms-body ms-aside-left-open ms-primary-theme"   id="body" >
                    {/*<Setting />*/}
                    <Sidenav/>
                    {/*<Recentactivity/>*/}
                    <main className="body-content">
                        <Navbar/>
                        <div className="ms-content-wrapper">
                            <div className="row">
                                <div className="col-md-12">
                                    <nav aria-label="breadcrumb">
                                        <ol className="breadcrumb pl-0">
                                            <li className="breadcrumb-item"><Link to="/"><i className="bx bxs-home"/> Home</Link></li>
                                            <li className="breadcrumb-item" aria-current="page"><Link to='/amin/payments'> <i className="fa fa-money-check-alt"/> Payments</Link></li>
                                            <li className="breadcrumb-item active" aria-current="page">{this.state.paymentId}</li>
                                        </ol>
                                    </nav>
                                </div>
                            </div>
                            <div style={{width:'30vw',borderRadius:'10px',padding:'20px',textAlign:'center'}}>
                                <Card>
                                    <Card.Header>
                                        <Barcode fontSize={10} background={`transparent`}width={2} height={50} value={payment.number}/>
                                    </Card.Header>
                                    <Card.Body>
                                        <div>
                                            <Row
                                                style={{
                                                    margin:'20px 0px 40px',

                                                }}
                                            />
                                            <div className={`text-left`}>
                                                <h4>{payment.paidBy}</h4>
                                                <h3>Total: <b className={`text-success`}>{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'KES' }).format(payment.amount)}</b></h3>

                                            </div>
                                            <Row
                                                style={{
                                                    margin:'20px 0px 40px',
                                                    border:'1px solid #efefef',
                                                }}
                                            />
                                            <Row>
                                                <Col sm={6} style={{textAlign:'left'}}>
                                                    <p><i className={`fa fa-info-circle`}/><span> Status: </span><span className={
                                                        payment.status==="NEW"? 'badge badge-warning text-dark':
                                                            payment.status==="CONFIRMED"?'badge badge-primary  text-dark':
                                                                payment.status==="PAID"?'badge badge-success  text-dark':'badge badge-danger  text-dark'
                                                    }>
                                                {payment.status}
                                            </span> </p>
                                                    <p><i className={`fa fa-receipt`}/><span> For Invoice: </span><b><span className={`text-dark`}>{payment.invoiceNo}</span></b></p>
                                                    <p><i className={`fa fa-feather-alt`}/><span> Description: </span><b><span className={`text-dark`}>{payment.description}</span></b></p>
                                                </Col>
                                                <Col sm={6} style={{textAlign:'right'}}>

                                                    <p><i className={`fa fa-money-check-alt`}/><span> Payment Method: </span><b><span className={`text-dark`}>{payment.method}</span></b></p>
                                                    <p><i className={`fa fa-money-bill-alt`}/><span> Mode: </span><b><span className={`text-dark`}>{payment.paymentMode}</span></b></p>
                                                    <p><i className={`fa fa-clock`}/><span> Paid On: </span><b><span className={`text-dark`}>{moment(payment.date).format("MMM Do YY h:mm a")} </span></b></p>
                                                </Col>
                                            </Row>
                                            <Row
                                                style={{
                                                    margin:'20px 0px 40px',

                                                }}
                                            />


                                        </div>
                                    </Card.Body>
                                    <Card.Footer>
                                        {payment.status==="NEW"?
                                            <Button onClick={()=>this.handleConfirmPayment(`${this.state.payment.id}`)} variant={`success`}>
                                                <i className={`fa fa-check-circle`}/> Mark Paid
                                            </Button>:
                                            <p>Payment confirmed by:<br/> <h5>{payment.confirmedBy? payment.confirmedBy:'ADMIN'}</h5></p>
                                        }
                                    </Card.Footer>
                                </Card>
                            </div>
                        </div>
                    </main>
                    {/*<Quickbar/>*/}
                </div>
            </Fragment>
        )
    }
}
