
    import React, {useEffect} from 'react';
    import DataTable from "../../../tables/DataTable";


    export default function UsersList(props) {
    const state = {
    title: 'Users',
    dataSource: 'application-users',
    actionUrl: 'application-user',
    keys: ['name','email','phoneNumber','role',"organisationName",'organisationCode'],
    titles: ['Name','email','phoneNumber','Role',"Organisation Name",'organisationCode'],
    numberFields: [],
    dateFields: [],
    displayActions:true,
        addStatus:11,
        filterObj:[],
    };
    const jss={
        container:{
            display:'flex',
            flexFlow:'row nowrap',
            justifyContent:'space-between',
            height:'80vh'
        },
        table:{
            flexGrow:2,
            backgroundColor:'#fff',
            borderRadius:'10px',
            overflow:'hidden',
        },
        userView:{
            flexGrow: 1,
            minWidth:'600px',
            backgroundColor:'#fff',
            borderRadius:'10px',
            margin:'0 10px',
        }
    }
    useEffect(()=>{

    },[props.update])


    const {title, keys, actionUrl, dataSource, titles, dateFields, numberFields,displayActions,addStatus,orgCode,filterObj} = state;
    return (
        <>
            <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                       dataSource={dataSource} dateFields={dateFields} titles={titles}
                       displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                       addStatus={addStatus}
            />
        </>
    )

    }
