import React, {Component, useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import UsersList from "./UsersList";
import {Col, Modal, Row} from "react-bootstrap";
import {Services} from "../../../../Services";
import {useForm, useWatch} from "react-hook-form";
import * as yup from "yup";
import swal from "sweetalert";


const Content =()=>{

    const[show,setShow]=useState(false)
    const[orgs,setOrgs]=useState([])
    const services = new Services(this);
    const onshowModal=()=>setShow(true);
    const onHideModal=()=>setShow(false);
    const {register,handleSubmit,control,formState:{errors}} = useForm();
    const [update,setUpdate]=useState(0);
  const [selectedOrg, setSelectedOrg]=useState({});
  const organisation = useWatch({
    control,
    name: "organisationCode",
    defaultValue: null
  });

  useEffect(()=>{
    for (let i = 0; i< orgs.length; i++){
      let o = orgs[i];
      if (o.code===organisation){
        setSelectedOrg(o)
      }
    }
  },[organisation])
const onSubmit=(values)=>{
    values.status="ACTIVE";
    values.imageUrl='';
    values.organisationName=selectedOrg.name
    services.addItem('application-user',values).then((resp)=>{
        services.onAddSuccess(resp);
        setUpdate(update+1);
    }).catch((err)=>{
        services.onAddFailed();
        console.warn(err);
    })
    onHideModal();

}
useEffect(()=> {
  services.getPaginated("organisations", '', 0, [])
    .then((res) => {
      setOrgs(res.data.data)
    }).catch((err) => {
    console.warn(err)
  })
},[show])

        return (
            <div className="ms-content-wrapper">
                <div className="row">
                    <Breadcrumb/>
                </div>
                <div className={`row`}>
                    <button style={{margin:'10px 15px 20px auto'}} onClick={onshowModal} className={`btn btn-primary`}>
                        <i className={`fa fa-plus`}/> Add User
                    </button>
                </div>
                <UsersList update={update}/>
                <Modal show={show} onHide={onHideModal} aria-labelledby="contained-modal-title-center" centered>
                    <Modal.Header onHide={onHideModal} closeButton className={`bg-primary`}>
                        <Modal.Title className="m-0">Add user</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                        <form onSubmit={handleSubmit(onSubmit)}>

                            <div className="form-group">
                                <label htmlFor="name">Name</label>
                                <input type="text"  {...register("name")} className="form-control" id="name" placeholder="Enter Name" />
                            </div>
                            <div className="form-group">
                                <label htmlFor="email">Email</label>
                                <input type="email"  {...register("email")}className="form-control" id="email" placeholder="Enter Email address"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="phone">Phone</label>
                                <input type="text"  {...register("phone")}className="form-control" id="phone" placeholder="Enter phone number"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="Role">Role</label>
                                <input type="text"  {...register("Role")}className="form-control" id="Role" placeholder="Enter Role"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="about">User Bio</label>
                                <textarea type="text"  {...register("about")}className="form-control" id="about" placeholder="Enter Short User Bio"/>
                            </div>
                            <div className="form-group">
                              <label htmlFor="organisationCode">Select Organisation</label>
                              <select type="select" {...register("organisationCode",{required:true})}
                                      className="form-control" id="organisationCode">
                                <option value={""} selected disabled hidden>Select Organisation</option>
                                {(orgs||[]).map((org,index) =>
                                  <option value={org.code} key={index}>{org.name}</option>
                                )}
                              </select>
                              <p className={"error text-danger"}>{errors.organisationCode?.type === 'required' && "*REQUIRED!! Please Select Organisation"}</p>
                            </div>
                            <div className="form-group">
                                <label htmlFor="defaultPassword">Default Password</label>
                                <input type="password"  {...register("defaultPassword")}className="form-control" id="defaultPassword" placeholder="Enter phone number"/>
                            </div>



                            <div>
                                <button type={`submit`} onClick={()=>onHideModal} style={{
                                    margin:'10px 15px 30px auto',
                                }} className={`btn btn-primary`}>
                                    <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}> Add User</span>
                                </button>
                            </div>
                        </form>
                    </Modal.Body>

                </Modal>
            </div>
        );

}

export default Content;
