
    import React from 'react';
    import DataTable from "../../../tables/DataTable";


    export default function StocksList(props) {
    const state = {
    title: 'Stocks Movement',
    dataSource: 'stocks',
    actionUrl: 'stock',
        keys: ['dateCreated',"organisationName",'number',"productName",'description', 'amount'],
        titles: ['Date',"Owner",'number',"product Name",'description', 'Amount In/ Out'],
    numberFields: [],
    dateFields: [],
    displayActions:false, filterObj:[],
    };

        const {title, keys, actionUrl, dataSource, titles, dateFields, numberFields,displayActions,orgCode,filterObj} = state;
        return (
            <>
                <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                           dataSource={dataSource} dateFields={dateFields} titles={titles}
                           displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                />
            </>
        )

    }
