import React, {Component, useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import ProductList from "./ProductList";
import {Services} from "../../../../Services";
import {useForm, useWatch} from "react-hook-form";
import * as yup from "yup";
import swal from "sweetalert";
import {Col, Modal, Row} from "react-bootstrap";


const Content=()=> {
    const[show,setShow]=useState(false);
    const[selectedOrg,setSelectedOrg]=useState({});
    const [organisations, setOrganisations]=useState([]);
    const services = new Services(this);
    const onshowModal=()=>setShow(true);
    const onHideModal=()=>setShow(false);
    const {register,handleSubmit,control} = useForm();
    const schemaResolver = yup.object().shape({

        name:yup.string().required(),
        email:yup.string().required(),
        phone:yup.string().required(),
        location:yup.string().required(),
        address:yup.string().required(),
        adminName:yup.string().required(),
        defaultPassword:yup.string().required(),

    })
  const selectedOrgCode=useWatch({
    control,
    name:"organisationCode",
  });
    useEffect(()=>{
      for (let i = 0; i< organisations.length; i++){
        let o = organisations[i];
        if (o.code===selectedOrgCode){
          setSelectedOrg(o);
        }
      }
    },[selectedOrgCode])
    const onSubmit=(values)=>{
        swal({
            title: "Add Product?",
            text: "Make sure all the data you filled in is correct",
            icon: "warning",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {
                  values.organisationName=selectedOrg.name
                    services.addItem('product',values).then(()=>{
                        swal("Product added Successfully",{
                            icon:'success',
                        }).then(()=>'')
                    })
                } else {
                    swal("Product not added", {
                        icon: "info",
                    }).then(() => '');
                }
            });
        onHideModal();

    }
    useEffect(()=>{
        services.getPaginated('organisations', '', 0, []).then((resp) =>{
            setOrganisations(resp.data.data);
        })
    },[])
    const jss={
        button:{
            display:'flex',
            justifyContent:'flex-end'
        }
    }
    const sleep = (time) => {
        return new Promise((resolve) => setTimeout(resolve, time));
    }

    return (
            <div className="ms-content-wrapper">
                <div className="row">
                    <Breadcrumb/>
                </div>
                <div className={`row`}>
                    <button style={{margin:'10px 15px 20px auto'}} onClick={onshowModal} className={`btn btn-primary`}>
                        <i className={`fa fa-plus`}/> Add Product
                    </button>
                </div>
                <ProductList/>
                <Modal show={show} onHide={onHideModal} aria-labelledby="contained-modal-title-center" centered>
                    <Modal.Header onHide={onHideModal} closeButton>
                        <Modal.Title className="m-0">Add Product</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                        <form onSubmit={handleSubmit(onSubmit)} resolver={schemaResolver}>
                            <div className="form-group">
                                <label htmlFor="name">Product Name</label>
                                <input type="text"  {...register("name")} className="form-control" id="name" placeholder="Enter Product Name" />
                            </div><div className="form-group">
                                <label htmlFor="description">Description</label>
                                <textarea type="text"  {...register("description")}className="form-control" id="description" placeholder="Enter Short Organisation Bio"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="unitPrice">Unit Price</label>
                                <input type="number"  {...register("unitPrice")}className="form-control" id="unitPrice" placeholder="Set Unit Price"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="image">image</label>
                                <input type="text"  {...register("image")}className="form-control" id="image" placeholder="Enter product image url"/>
                            </div>
                            <div className="form-group">
                                <label htmlFor="organisationCode">Organisation</label>
                                <select  {...register("organisationCode")} className="form-control" id="organisationCode" placeholder="Enter Product Name">
                                    <option value={``} selected disabled hidden>Select organisation</option>
                                    {organisations.map((org,index)=>
                                        <option key={index} value={org.organisationCode}>{org.name}</option>
                                    )}
                                </select>
                            </div>

                            <div style={jss.button} >
                                <button type={`submit`} onClick={()=>onHideModal} style={{
                                    margin:'10px 15px 30px auto',
                                }} className={`btn btn-primary`}>
                                    <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}> Add Product</span>
                                </button>
                            </div>
                        </form>
                    </Modal.Body>

                </Modal>
            </div>
        );
}

export default Content;
