
    import React from 'react';
    import DataTable from "../../../tables/DataTable";


    export default function PaymentList(props) {
    const state = {
    title: 'Payments',
    dataSource: 'payments',
    actionUrl: 'payment',
        keys: ['dateCreated',"organisationName",'number','paidBy','amount','description','method','confirmedBy'],
        titles: ['Date',"Organisation Name",'number','paidBy','amount','description','method','confirmedBy'],
    numberFields: [],
    dateFields: [],
    displayActions:true,
        addStatus:13,
        filterObj:[],
    };

        const {title, keys, actionUrl, dataSource, titles, dateFields, numberFields,displayActions,addStatus,orgCode,filterObj} = state;
        return (
            <>
                <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                           dataSource={dataSource} dateFields={dateFields} titles={titles}
                           displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                           addStatus={addStatus}
                />
            </>
        )

    }
