import React from "react";
import logo from '../../../assets/img/logo.svg'
import {Button, Card, Col, Row} from "react-bootstrap";
import * as yup from 'yup';
import {useForm} from 'react-hook-form';
import {Services} from "../../../Services";



const Login=()=>{
    const {register,handleSubmit} = useForm();
    const schemaResolver = yup.object().shape({
        password: yup.string().required(),
        email: yup.string().email(),
    })
    const jss={
        loginWrapper:{
            display:'flex',
            flexFlow:'row nowrap',
            justifyContent:'center',
            alignItems:'center',
            width:'100vw',
            height:'100vh',
            background:'#e3e3e9'
        },
        loginForm:{
            height:'40wh',
            padding:'30px 50px',
            background:'#fff',
          margin:"0 auto",
            borderRadius:'20px',
        },
        logo:{
            width:'100px',
            margin:'0 auto'
        },
        logoWrapper:{
            textAlign:'center',
        },
        button:{
            width:'100%',
        }
    }
    const services=new Services(this)
    const onSubmit=data=>{
        services.login(data);

    }
    return (
            <>
                    <div style={jss.loginWrapper}>
                      <Row style={{display:"grid",placeItems:"center"}}className={"w-100"}>
                        <Col md={6} sm={9} xs={12}>
                          <Card style={jss.loginForm}className="ms-panel-body">
                            <div style={jss.logoWrapper}>
                              <img style={jss.logo} src={logo} alt={`logo`}/>
                            </div>
                            <form onSubmit={handleSubmit(onSubmit)} resolver={schemaResolver}>
                              <div className="form-group">
                                <label htmlFor="email">Email address</label>
                                <input type="email" {...register("email")} className="form-control" id="email" placeholder="name@example.com" />
                              </div>
                              <div className="form-group">
                                <label htmlFor="password">Password</label>
                                <input type="password"  {...register("password")} className="form-control" id="password" placeholder="Password" />
                              </div>
                              <Button style={jss.button} type='submit' className='btn btn-success'>
                                Login
                              </Button>
                            </form>
                          </Card>
                        </Col>
                      </Row>
                    </div>
            </>
        )
}

export default Login;
