import React, {Component, useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import OrdersList from "./OrdersList";
import {AutoComplete, Modal} from 'antd';
import {Button} from "react-bootstrap";
import {useForm} from "react-hook-form";
import * as yup from "yup";
import {Services} from "../../../../Services";
import swal from "sweetalert";


const Content=()=> {

    const [isModalVisible,setIsModalVisible]=useState(false);
    const [orderData,setOrderData]=useState({});

    const {register,handleSubmit} = useForm();
    const [products,setProducts]=useState([]);

    const [update,setUpdate]=useState('init')
    const services = new Services(this)
    useEffect(()=>{
        services.getPaginated("products", '', 0, []).then((res)=>{
            setProducts(res.data.data)
        }).catch((err)=>{
            console.warn(err)
        })
    }, [update])
    const [options, setOptions] = useState([]);
    const [selectedOrg, setSelectedOrg]=useState({});
    const [organisationCode,setOrganisationCode]=useState("");
    const searchRes=async(organisationSelect)=>{
      try {
        let orgs=[];
        (organisationSelect.data.data||[]).map(item=>{
          item.value=item.name;
          item.label=item.name;
          orgs.push(item);
        })
        return orgs
      }catch(err) {
        console.log(err)
      }
    }
    const onSearch = async (searchText) => {
      const searchOrganisations= await services.getPaginated("organisations",searchText,0,[]);
      const namesArr=await searchRes(searchOrganisations);
      try {
        setOptions(namesArr);
      }catch(err){
        console.log(err);
      }
    };
    const onSelect = (selectedName) => {
      for (let i = 0; i< options.length; i++){
        let o = options[i];
        if(o.name===selectedName) {
          setSelectedOrg(o);
          setOrganisationCode(o.code);
          console.log(o, selectedName)
        }
      }
    };
    const schemaResolver = yup.object().shape({
        selectProduct: yup.string().required(),
        quantity: yup.string().required(),
        deliveryAddress: yup.string().required(),

    })
    const showModal=()=>{
        setIsModalVisible(true)
    }
    const closeModal=()=>{
        setIsModalVisible(false)
    }


    const onSubmit=data=>{
        onHandleSubmit(data)
    }
    const createID=(x)=>{
        return (Math.random() + 1).toString(36).substring(x);
    }
    const onHandleSubmit = (values) => {
      const lpoNumber = createID(2);
      const unitPrice = 549;
      const totalAmount = unitPrice * values.quantity;
      services.getItem('product', values.product)
        .then((res) => {
          sleep(1000).then(() => {
            services.addItem('order', {
              quantity: values.quantity,
              lpoNumber: lpoNumber.toUpperCase(),
              deliveryLocation: values.deliveryLocation,
              orderedBy: values.orderedBy,
              productName: res.data.name,
              productImage: res.data.image,
              description: res.data.description,
              status: "NEW",
              totalAmount: totalAmount,
              unitPrice: res.data.unitPrice,
              organisationCode: selectedOrg.code,
              organisationName: selectedOrg.name
            }).then((ord) => {
              services.addItem("order-item", {
                description: res.data.description,
                orderCode: ord.data.serviceReturnValue,
                organisationCode: selectedOrg.code,
                organisationName: selectedOrg.name,
                productCode: res.data.code,
                productImage: res.data.image,
                productName: res.data.name,
                quantity: values.quantity,
                status: "PENDING DISPATCH",
                totalAmount: res.data.unitPrice * values.quantity,
                unitPrice: res.data.unitPrice,
              }).then(r => {
                swal(`Successfully created order`, {
                  icon: "success",
                }).then(() => {
                  setUpdate("update")
                });

              })
            })
          })

        })
    }

    const jss={
        button:{
            display:'flex',
            justifyContent:'flex-end'
        }
    }
    const sleep = (time) => {
        return new Promise((resolve) => setTimeout(resolve, time));
    }
    return (
            <div className="ms-content-wrapper">
                <div className="row">
                    <Breadcrumb/>
                </div>
                <div className="row" >
                    <button onClick={showModal} style={{
                        margin:'10px 15px 30px auto',
                    }} className={`btn btn-primary`}>
                        <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}> Create Order</span>
                    </button>
                </div>
                <OrdersList/>
                <Modal
                    title={`Create Order`}
                    centered
                    visible={isModalVisible}
                    footer={null}
                    onClose={closeModal}
                >
                    <form onSubmit={handleSubmit(onSubmit)} resolver={schemaResolver}>
                      <div className="form-group">
                        <label htmlFor="organisationCode">Organisation</label>
                        <AutoComplete
                          options={options}
                          style={{ width: 200 }}
                          onSelect={onSelect}
                          onSearch={onSearch}
                          className="b-block w-100"
                          id="organisationCode"
                          placeholder="search organisation"
                        />
                      </div>
                       <div className="form-group">
                            <label htmlFor="product">Select Product</label>
                            <select type="select" {...register("product")}
                                    className="form-control" id="product">
                               {(products||[]).map((product,index) =>
                                    <option value={product.code} key={index}>{product.name}</option>
                                )}
                            </select>
                        </div>
                        <div className="form-group">
                            <label htmlFor="quantity">Quantity</label>
                            <input type="number"  {...register("quantity")} className="form-control" id="quantity" placeholder="Enter Quantity" />
                        </div>
                        <div className="form-group">
                            <label htmlFor="deliveryLocation">Delivery Address</label>
                            <input type="text"  {...register("deliveryLocation")} className="form-control" id="deliveryLocation" placeholder="Enter Delivery Address" />
                        </div>
                        <div className="form-group">
                            <label htmlFor="address">Ordered BY</label>
                            <input type="text"  {...register("orderedBy")}className="form-control" id="deliveryAddress" value={localStorage.getItem('name')} />
                        </div>
                        <div style={jss.button} >
                            <button type={`submit`} onClick={closeModal} style={{
                                margin:'10px 15px 30px auto',
                            }} className={`btn btn-primary`}>
                                <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}> Create Order</span>
                            </button>
                        </div>
                    </form>

                </Modal>
            </div>
        );
}

export default Content;
