import React, {Fragment, useEffect} from "react";
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Tabs} from "antd";
import {Link} from "react-router-dom";
import {Button, Row,Col,Card} from 'react-bootstrap';
import {Services} from "../../../../Services";
import classNames from "classnames";
import moment from "moment";
import 'antd/dist/antd.css';
import swal from "sweetalert";

const {TabPane} =Tabs;

export default class ViewOrder extends React.Component{

    constructor(props) {
        super(props);
        this.state={
            row:props.match.params,
            order:{},
            orderItems:[],
            status:'',
          organisation:{},
            filterObj:[{
                'key':'orderCode',
                'value':`${props.match.params.id}`}],
              itemUrl:'/order-items',
              search:'',
              page:0,
              limit:40,
          show:false,
          product:{},


        }
        this.services=new Services(this);


    }
    onShow=()=>this.setState({show:true})
    onHide=()=>this.setState({show:false})

    getOrder=()=>{
        this.services.getItem('order',this.state.row.id)
            .then((res)=>{
                this.setState({order:res.data});
        }).then(()=>{
          this.getOrderItems();
          this.getOrderOrg();
        })
          .catch((err) => {
            console.warn(err);
        });
    }
    getOrderItems=()=>{
        let{itemUrl,search,page,filterObj}=this.state;
        this.services.getPaginated(itemUrl,search,page,filterObj)
            .then((res)=>{
                this.setState({orderItems:res.data.data},()=>'')
            })
    }
    getOrderOrg=()=>{
      this.services.getItem('/organisation',this.state.order.organisationCode)
        .then((resp)=>{
          this.setState({organisation:resp.data})
        })
    }
    handleItemDispatch=(item)=>{
      let data=item
      data.status="DISPATCHED";
      this.services.editItem('order-item',data)
        .then((res)=>{
          this.setState({product:item},()=>{/*this.onShow()*/});
          this.forceUpdate();
        }).catch((err)=>{
          console.warn(err);
      })
    }
    componentDidMount() {
        this.getOrder();
    }

    render() {
        const {order,orderItems}=this.state;
        return (
            <Fragment>
                <MetaTags>
                    <title>Taam | Users</title>
                    <meta
                        name="description"
                        content="#"
                    />
                </MetaTags>
                <div className="body ms-body ms-aside-left-open ms-primary-theme"   id="body" >
                    {/*<Setting />*/}
                    <Sidenav/>
                    {/*<Recentactivity/>*/}
                    <main className="body-content">
                        <Navbar/>
                        {/*<CreateDelivery
                          show={this.state.show}
                          onHide={this.onHide}
                          products={this.state.products}
                          product={this.state.product}
                          org={this.state.order.organisationCode}
                        />*/}

                        <div className="ms-content-wrapper">
                            <div className="row">
                                <div className="col-md-12">
                                    <nav aria-label="breadcrumb">
                                        <ol className="breadcrumb pl-0">
                                            <li className="breadcrumb-item"><Link to="/"><i className="bx bxs-home"/> Home</Link></li>
                                            <li className="breadcrumb-item" aria-current="page"><Link to='/orders'> <i className="fa fa-shopping-basket"/>Orders</Link></li>
                                            <li className="breadcrumb-item active" aria-current="page">{this.state.row.id}</li>
                                        </ol>
                                    </nav>
                                </div>
                            </div>
                            <div>
                                <Row>
                                    <Col>
                                        <Card>
                                            <Card.Body>
                                                <Row>

                                                    <Col md={4}>
                                                        <p style={{margin:0}}><i className={`fa fa-info-circle`}/> Status: <span
                                                            className={classNames('badge', {
                                                                'badge badge-danger text-light': order.status === 'PENDING',
                                                                'badge badge-success text-dark': order.status === 'COMPLETED',
                                                                'badge badge-warning text-dark ': order.status === 'NEW',
                                                                'badge badge-primary  text-light': order.status === 'DISPATCHED',
                                                                'badge badge-success  text-light': order.status === 'DELIVERED',
                                                                'badge badge-light  text-light': order.status === 'CANCELLED',
                                                            })}
                                                        >
                                                    {order.status}
                                                </span></p>
                                                      <p style={{margin:0}}><i className="fa fa-map-marker-alt"/>Delivered to: <b>{order.deliveryLocation}</b></p>
                                                      <p style={{margin:0}}><i className="fa fa-user-astronaut"/>Ordered By: <b>{order.orderedBy}</b></p>
                                                      <p style={{margin:0}}><i className="fa fa-building"/>Organisation: <b>{order.organisationName}</b></p><br/>
                                                    </Col>
                                                    <Col md={4}>

                                                        <p style={{margin:0}}>
                                                          <span><i className="fa fa-calendar-alt"/> Created <b>{moment(order.dateCreated).format("MMM Do YYYY")}</b> <br/>
                                                        </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                          <span><i className="fa fa-clock"/> Departure:  <b>{moment(order.timeOfDeparture).format("MMM Do YYYY")}</b></span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                          <span><i className="fa fa-clock"/> Arrival : <b>{moment(order.dateCreated).format("MMM Do YYYY")}</b></span>
                                                        </p><br/>
                                                    </Col>
                                                    <Col md={4} style={{textAlign:'right'}}>


                                                        {order.status === "NEW"? (
                                                            <div>
                                                                <Button onClick={()=>this.handleConfirmOrder(order.id)} className="btn-sm w-75 btn-success waves-effect waves-light float-end">
                                                                <i className='fa fa-check-circle'/> Confirm Order
                                                            </Button>
                                                                <br/>

                                                                <Button onClick={()=>this.handleRejectOrder(order.id)} className="btn-sm w-75 btn-warning waves-effect waves-light float-end">
                                                                    <i className='fa fa-exclamation-triangle'/> Reject Order
                                                                </Button>

                                                            </div>
                                                        ): order.status === "PENDING"?
                                                            <div>
                                                                <Button onClick={()=>this.handleDispatchOrder(order.id)} className="btn-sm w-75 btn-primary waves-effect waves-light float-end">
                                                                    <i className='fa fa-truck-moving'/> Dispatch Order
                                                                </Button>
                                                                <br/>

                                                                <Button onClick={()=>this.handleRejectOrder(order.id)} className="btn-sm w-75 btn-danger waves-effect waves-light float-end">
                                                                    <i className='fa fa-exclamation-triangle'/> Cancel Order
                                                                </Button>

                                                            </div>:
                                                            order.status === "DISPATCHED"?
                                                                <div>
                                                                    <Button onClick={()=>this.handleCreateDelivery(order.id)} className="btn-sm w-75 btn-primary waves-effect waves-light float-end">
                                                                        <i className='fa fa-parachute-box'/> Create Delivery
                                                                    </Button>
                                                                    <br/>
                                                                   {/* <Button onClick={()=>this.handleConfirmDelivery(order.id)} className="btn-sm w-75 btn-success waves-effect waves-light float-end">
                                                                        <i className='fa fa-truck-loading'/> Confirm Delivery
                                                                    </Button>
                                                                    <br/>

                                                                    <Button onClick={()=>this.handleRejectOrder(order.id)} className="btn-sm w-75 btn-danger waves-effect waves-light float-end">
                                                                        <i className='fa fa-exclamation-triangle'/> Cancel Order
                                                                    </Button>*/}

                                                                </div>:
                                                                order.status === "DELIVERED"?
                                                                    <div>
                                                                        <Button onClick={()=>this.handleCreateInvoice(order.id)} className="btn-sm w-75 btn-primary waves-effect waves-light float-end">
                                                                            <i className='fa fa-receipt'/> Create Invoice
                                                                        </Button>
                                                                        <br/>
                                                                        <Button onClick={()=>this.handleMarkComplete(order.id)} className="btn-sm w-75 btn-success waves-effect waves-light float-end">
                                                                            <i className='fa fa-check-double'/> Mark Complete
                                                                        </Button>
                                                                        <br/>

                                                                        <Button onClick={()=>this.handleRejectOrder(order.id)} className="btn-sm w-75 btn-danger waves-effect waves-light float-end">
                                                                            <i className='fa fa-exclamation-triangle'/> Cancel Order
                                                                        </Button>

                                                                    </div>:
                                                                    order.status === "COMPLETE"?
                                                                        <div>
                                                                            <Button onClick={()=>this.handleViewInvoice(order.id)} className="btn-sm w-75 btn-primary waves-effect waves-light float-end">
                                                                                <i className='fa fa-receipt'/> View Invoice
                                                                            </Button>

                                                                        </div>:
                                                                    order.status === "CANCELLED"?
                                                                        <div>
                                                                            <Button onClick={()=>this.handleRestoreOrder(order.id)} className="btn-sm w-75 btn-warning waves-effect waves-light float-end">
                                                                                <i className='fa fa-history'/> Restore Order
                                                                            </Button>
                                                                            <br/>

                                                                            <Button onClick={()=>this.handleDelete(order.id)} className="btn-sm w-75 btn-danger waves-effect waves-light float-end">
                                                                                <i className='fa fa-trash-alt'/> Delete Order
                                                                            </Button>

                                                                        </div>:null

                                                        }
                                                    </Col>
                                                </Row>
                                                <Tabs
                                                    tabBarStyle={this.jss.vUserTabs.tabsPane}
                                                    tabPosition='top'>
                                                    <TabPane tab={
                                                        <span  style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-list'/>
                                                                    <i> </i> Order items</span>

                                                    } key="1">
                                                        <div  style={this.jss.vUserTabs.tabContent}>
                                                          <table  className="table table-striped table-light table-sm">
                                                            <thead>
                                                            <tr className={`bg-light text-light bold`}>
                                                              <td>Code</td>
                                                              {/*<td>Image</td>*/}
                                                              <td>Name</td>
                                                              <td>Description</td>
                                                              <td>unitPrice</td>
                                                              <td>Quantity</td>
                                                              <td>Total</td>
                                                              <td>Status</td>
                                                              <td>Actions</td>
                                                            </tr>
                                                            </thead>
                                                            <tbody>
                                                            {orderItems.map((item,index)=>
                                                              <tr key={item.code}>
                                                                <td className="align-baseline">{item.productCode}</td>
                                                                {/*<td className="align-baseline"><img
                                                                  src={item.productImage}
                                                                  alt={item.name}/>
                                                                </td>*/}
                                                                <td className="align-baseline">{item.productName}</td>
                                                                <td className="align-baseline">{item.description}</td>
                                                                <td className="align-baseline">{item.unitPrice}</td>
                                                                <td className="align-baseline">{item.quantity}</td>
                                                                <td className="align-baseline bold" >{item.totalAmount}</td>
                                                                <td className="align-baseline">
                                                                  {item.status!==null?
                                                                    <span className={`badge badge-sm badge-primary`}>{item.status}</span> :
                                                                    <span className={`badge badge-sm badge-warning`}>{`PENDING DISPATCH`}</span>}</td>
                                                                <td className="align-baseline">
                                                                  {item.status!==null?'' || item.status!=="PENDING":<button type={`button`}
                                                                                                 className={`btn 
                                                                                                 ${order.status!=="NEW"&&order.status!=="CANCELLED"?"btn-primary":"btn-light"} btn-sm`}
                                                                                                 onClick={()=>{
                                                                                                   order.status!=="NEW"&&order.status!=="CANCELLED"?this.handleItemDispatch(item):alert("Confirm Order to dispatch Product!")
                                                                                                 }}>Dispatch</button>}
                                                                </td>
                                                                </tr>
                                                            )}
                                                            </tbody>
                                                          </table>

                                                        </div>
                                                    </TabPane>
                                                </Tabs>

                                            </Card.Body>
                                        </Card>
                                    </Col>
                                </Row>
                            </div>
                        </div>
                    </main>
                    {/*<Quickbar/>*/}
                </div>
            </Fragment>
        )
    }
    jss={
        vUserTabs: {
            marginTop: '60px',
            tabsPane: {
                color: '#00897B',
                fontWeight: 600,
                marginTop: 40,
                tab: {
                    padding: '5px 10px',
                    borderRadius: '5px',
                    fontWeight: 600,
                    backgroundColor: '#f3f3f9',
                    margin: 0
                }

            },
            tabContent: {
                padding: '10px 20px',
                backgroundColor: 'transparent',
                borderRadius: '10px',
            }

        }
    }

    handleDelete(code) {
        swal({
            title: "Delete Order?",
            text: "Once you delete an Order, You cannot retrieve it!",
            icon: "warning",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.deleteItem('order',code).then(()=>{
                        swal("Order Successfully Deleted", {
                            icon: "info",
                        }).then(() => {
                            this.props.history.push('/orders')
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleConfirmOrder(id) {
        swal({
            title: "Confirm Order?",
            text: "Are you sure you want to accept order?",
            icon: "info",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"PENDING","ORDER").then(()=>{
                        swal("Order Successfully Confirmed ", {
                            icon: "success",
                        }).then(()=> {
                            this.forceUpdate();
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleRejectOrder(id) {
        swal({
            title: "Reject Order?",
            text: "Are you sure you want to cancel this order?",
            icon: "warning",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"CANCELLED","ORDER").then(()=>{
                        swal("Order Successfully Rejected ", {
                            icon: "success",
                        }).then(()=> {
                            this.forceUpdate();
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleDispatchOrder(id) {
        swal({
            title: "Dispatch Order?",
            text: "Make sure that a delivery truck has been dispatched",
            icon: "info",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"DISPATCHED","ORDER").then(()=>{
                        swal("Order Successfully Dispatched ", {
                            icon: "success",
                        })
                      this.forceUpdate();
                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleConfirmDelivery(id) {
        swal({
            title: "Confirm Delivery?",
            text: "Once Confirmed, you can create Deliveries",
            icon: "info",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"DELIVERED","ORDER").then(()=>{
                        swal("Order Successfully Delivered ", {
                            icon: "success",
                        }).then(()=> {
                            this.forceUpdate();
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleMarkComplete(id) {
        swal({
            title: "Mark Complete?",
            text: "Mark an order complete only when it's done",
            icon: "info",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"COMPLETE","ORDER").then(()=>{
                        swal("Order Completed", {
                            icon: "success",
                        }).then(()=> {
                            this.forceUpdate();
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }
    handleRestoreOrder(id) {
        swal({
            title: "Restore Order?",
            text: "Restore order to fulfill it",
            icon: "info",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.updateModelStatus(id,"PENDING","ORDER").then(()=>{
                        swal("Order Restored", {
                            icon: "success",
                        }).then(()=>{
                            this.forceUpdate();
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleViewInvoice(id) {
        return undefined
    }

    handleCreateInvoice(id) {
        return undefined;
    }

    handleCreateDelivery(id) {
        return undefined;
    }
}
