
    import React from 'react';
    import DataTable from "../../../tables/DataTable";


    export default function DeliveriesList(props) {
    const state = {
      title: 'Deliveries',
      dataSource: 'deliveries',
      actionUrl: 'delivery',
      keys: ['dateCreated', "organisationName", 'location', 'mode', 'truck', 'quantity', 'unitPrice', 'deliveredBy', 'receivedBy'],
      titles: ['Date Created', "Organisation Name", 'Location', 'Mode', 'truck', 'quantity', 'unitPrice', 'Driver', 'Recipient'],
      numberFields: [],
      dateFields: [],
      displayActions: true,
      addStatus: 14,
      filterObj: [],
    };

        const {title, keys, actionUrl, dataSource, titles, dateFields, numberFields,displayActions,addStatus,orgCode,filterObj} = state;
        return (
            <>
                <DataTable title={title} keys={keys} actionUrl={actionUrl} numberFields={numberFields}
                           dataSource={dataSource} dateFields={dateFields} titles={titles}
                           displayActions={displayActions} orgCode={orgCode} filterObj={filterObj}
                           addStatus={addStatus}
                />
            </>
        )

    }
