import React, {Suspense, useEffect, useState} from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import Sidenav from "./components/layouts/Sidenav";
import Users from "./components/pages/mainPages/users/Users";
import Orders from "./components/pages/mainPages/orders/Orders";
import Deliveries from "./components/pages/mainPages/deliveries/Deliveries";
import Invoices from "./components/pages/mainPages/invoices/Invoices";
import Payments from "./components/pages/mainPages/payments/Payments";
import Locations from "./components/pages/mainPages/locations/Locations";
import Stocks from "./components/pages/mainPages/stocks/Stocks";
import Trucks from "./components/pages/mainPages/trucks/Trucks";
import Organisations from "./components/pages/mainPages/organisations/Organisations";
import Products from "./components/pages/mainPages/products/Products";
import ViewOrder from "./components/pages/mainPages/orders/ViewOrder";
import ViewDeliveries from "./components/pages/mainPages/deliveries/ViewDeliveries";
import Login from "./components/pages/auth/Login";
import Lockscreen from "./components/pages/prebuilt-pages/Lockscreen";
import ViewInvoices from "./components/pages/mainPages/invoices/ViewInvoices";
import 'bootstrap/dist/css/bootstrap.min.css';
import ViewOrg from "./components/pages/mainPages/organisations/ViewOrg";
import ViewPayment from "./components/pages/mainPages/payments/ViewPayment";
import ViewUser from "./components/pages/mainPages/users/ViewUser";
import ViewProduct from "./components/pages/mainPages/products/ViewProduct";
import "./assets/css/invoice.css"

// Preloader
const Preloader = React.lazy(() => import("./components/layouts/Preloader"));
// Pages
const Home = React.lazy(() => import("./components/pages/Home"));


function App() {

    const isLoggedIn=localStorage.getItem('AuthToken');

  return (
     <Router>

      <Suspense fallback={<div></div>}>
        <Preloader />
          {isLoggedIn?


                <>
                <Switch>
                <Route exact path="/admin/" component={Home} />
                <Route exact path='/admin/users' component={Users}/>
                <Route exact path='/admin/application-users/:id' component={ViewUser}/>
                <Route exact path='/admin/orders' component={Orders}/>
                <Route path='/admin/orders/:id' component={ViewOrder}/>
                <Route exact path='/admin/deliveries' component={Deliveries}/>
                <Route path='/admin/deliveries/:id' component={ViewDeliveries}/>
                <Route exact path='/admin/invoices' component={Invoices}/>
                <Route exact path='/admin/payments' component={Payments}/>
                <Route exact path='/admin/locations' component={Locations}/>
                <Route exact path='/admin/stocks-movement' component={Stocks}/>
                <Route exact path='/admin/fleet' component={Trucks}/>
                <Route exact path='/admin/orgs' component={Organisations}/>
                <Route exact path='/admin/organisations/:id' component={ViewOrg}/>
                <Route exact path='/admin/payments/:id' component={ViewPayment}/>
                <Route exact path='/admin/products' component={Products}/>
                <Route exact path='/admin/products/:id' component={ViewProduct}/>
                <Route exact path='/admin/invoices/:id' component={ViewInvoices}/>
                </Switch>
                </>:
                <>
                    <Switch>
                    <Route path='/admin/login' component={Login}/>
                    <Route path='/admin/' component={Login}/>
                    </Switch>
                </>

            }

      </Suspense>
    </Router>
  );
}

export default App;
