import React from 'react';
import { ThemeProvider } from "@mui/styles";
import PropTypes from 'prop-types';
import MUIDataTable from "mui-datatables";
import IconButton from "@material-ui/core/IconButton";
import EditIcon from "@material-ui/icons/Edit";
import {red} from "@material-ui/core/colors";
import DeleteIcon from "@material-ui/icons/Delete";
import RemoveRedEye from "@material-ui/icons/RemoveRedEye";
import {createTheme} from "@mui/material/styles";
import swal from 'sweetalert';
import apiStore from "../../api/apiStore";
import moment from "moment";
import {Link} from "react-router-dom";
import classNames from "classnames";

export const tableStyles = theme => ({
    table: {
        border: '1px solid #e7e7e7',
        borderRadius: '10px',
        fixedHeader: true,
        fontSize: '12px',
        height: '80vh',
        overflowY: 'hidden',
        position: 'relative',
        '& ::-webkit-scrollbar': {
            width: '5px',
            borderRadius: '10px'
        },
        '& ::-webkit-scrollbar-track': {
            borderRadius: '2px',
            backgroundColor: 'transparent'
        },
        '& ::-webkit-scrollbar-thumb': {
            borderRadius: '2px',
            backgroundColor: '#0054d1'
        },

        '& > div': {
            overflowY: 'scroll',
            height: '100%',

        },
        '& table': {

            '& td': {
                wordBreak: 'keep-all',
                fontSize: '13px'
            },
            [theme.breakpoints.down('md')]: {
                '& td': {
                    height: 60,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis'
                }
            }
        }
    },
});

class MyTable extends React.Component {
    state={

    }
    actionButtons = {
        name: 'ACTIONS',
        options: {
            filter: false,
            searchable: false,
            sort: false,
            sortThirdClickReset: true,
            customBodyRender: (dataIndex, row) => {
                return (<>

                    <IconButton aria-label="Delete"  onClick={this.handleDelete(row)}>
                        <DeleteIcon className={'text-danger'}/>
                    </IconButton>
                    <Link to={
                        {
                            pathname:`${this.state.dataSource}/${row.rowData[1]}`,
                            params:row.rowData
                        }
                        } aria-label="View" onClick={this.handleViewClicked(row)}>
                        <RemoveRedEye  className={'text-primary'}/>
                    </Link>
                </>);
            }
        }
    }
    viewStatus = {
        name: 'STATUS',
        options: {
            filter: true,
            searchable: false,
            sort: false,
            sortThirdClickReset: true,
            display:true,
            customBodyRender: (dataIndex, row) => {
                let status=row.rowData[this.props.addStatus]
                return (<>
                    <span className={
                        status==="NEW"? `badge bg-primary text-light`:
                        status==="DISPATCHED"? `badge bg-info text-light`:
                        status==="DELIVERED"? `badge bg-warning text-dark`:
                        status==="COMPLETE"? `badge bg-success text-light`:
                        status==="CANCELLED"? `badge bg-light text-light`:
                        status==="PENDING"? `badge bg-warning text-dark`:
                        status==="ACTIVE"? `badge bg-success text-light`:
                        status===null? `badge bg-danger text-light`:
                        status==="PAID"? `badge bg-success text-light`:`badge bg-dark text-light`
                    }> {status!==null? status:"NULL"} </span>
                </>);
            }

        }
    }
    idColumn = {
        name: 'ID',
        options: {
            filter: false,
            searchable: false,
            display: false,
            sortThirdClickReset: true,
            sort: false,
        }
    }
    codeColumn = {
        name: '#',
        options: {
            filter: false,
            searchable: false,
            sort: false,
            sortThirdClickReset: true,
            display:false,
        }
    }
    createdByColumn = {
        name: 'Created By',
        options: {
            filter: true,
            searchable: false,
            sort: false,
            sortThirdClickReset: true,
            display: false,
        }
    }
    organisationCodeColumn = {
        name: 'Organisation Code',
        options: {
            filter: true,
            searchable: false,
            sort: false,
            sortThirdClickReset: true,
            display:false
        }
    }
    avatar = {
        name: 'PROFILE',
        options: {
            filter: false,
            searchable: false,
            sort: false,
            sortThirdClickReset: false,
            display: false,
            customBodyRender: (dataIndex, row) => {
                return (<>
                    <img src={row.rowData[7]} alt={`user`}/>
                </>);
            }

        }
    }
    dateCreatedColumn = {
        name: 'Date Created',
        options: {
            filter: false,
            sortThirdClickReset: true,
            sortDescFirst: true,
            searchable: false,
            display: false,
            customBodyRender: (value) => {
                return moment(value).format("MMM Do YY");
                // const d = new Date(value);
                // return d.toLocaleString();
            }
        }
    }
    dueDateColumn = {
        name: 'Due Date',
        options: {
            filter: false,
            sortThirdClickReset: true,
            sortDescFirst: true,
            searchable: false,
            display: false,
            customBodyRender: (dataIndex, row) => {
                //return moment(row.rowData[10]).format("MMM Do YY");
              return row.rowData[10]
            }
        }
    }
    saveAction = {
        name: 'Actions',
        options: {
            filter: false,
            searchable: false,
            sortThirdClickReset: true,
            customBodyRender: (dataIndex, row) => {
                return (
                    <>
                        {/*<IconButton aria-label="Save" onClick={this.saveEdited(row)}>*/}
                        {/*    <SaveIcon/>*/}
                        {/*</IconButton>*/}
                    </>
                );
            }
        }
    }
    constructor(props) {
        super(props);
        this.state = {
            addFormOpen: false,
            title: props.title,
            dataSource: props.dataSource,
            actionUrl: props.actionUrl,
            keys: props.keys,
            titles: props.titles,
            sortColumns:props.sortColumns,
            numberFields: props.numberFields,
            dateFields: props.dateFields,
            limit: 20,
            page: 0,
            count: 0,
            sortKey: props.sortKey===undefined? "" : props.sortKey,
            sortValue: props.sortValue===undefined? 0 : props.sortValue,
            search: '',
            filterKey: '',
            filterValue: '',
            filterList: [],
            error: false,
            isLoading: false,
            errorMessage: null,
            filterObj: props.filterObj,
            editMode: false,
            data: [],
            editRow: null,
            responseData: []
        };
        this.createColumns();


        this.AUTH = {
            Authorization: `Bearer ${localStorage.getItem('AuthToken')}`,
            'Access-Control-Allow-Origin': '*',
            'X-AT': 'Q'
        };
        this.CONFIG = { headers: this.AUTH };
    }

    handleDelete = item => () => {
        let id = item.rowData[0];
        this.delete(id)
    }
    delete = (id) =>{
        swal({
            title: "Are you sure?",
            text: "Once deleted, you will not be able to recover this data!",
            icon: "warning",
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {
                    this._performDelete(`${this.state.actionUrl}/${id}`, this.onDeleteSuccess)
                } else {
                    swal.close();
                }
            });
    }

    _performDelete = (url, callback, ...kwargs) =>{

        apiStore.delete(url)
            .then((response) => {
                const { data } = response;
                if (callback !== undefined) {
                    return callback(data, kwargs);
                }
                return true;
            })
            .catch((error) => this.__handleCatch(error))
    }

    onDeleteSuccess = (data) =>{
        const _this = this;
        swal("Poof! Your item has been deleted!", {
            icon: "success",
        });
        this.updateDataTable();
        this.setState({
            isLoading: false,
            error: false,
            errorMessage: '',
            warning: false,
            addFormOpen: false
        })
        setTimeout(() => {
            swal.close();
        }, 1500);
    }

    createColumns = () =>{
        const  _this = this
        this.options = {
            filterType: 'textField',
            responsive: 'standard',
            print: false,
            count: this.state.count,
            rowsPerPage: this.state.limit,
            page: this.state.page,
            searchText: this.state.search,
            searchAlwaysOpen: false,
            selectableRows: "single",
            serverSide: true,
            jumpToPage: true,
            downloadOptions: {
                filename: `${this.state.title}.csv`,
                separator: ','
            },
            rowsPerPageOptions: [2, 10, 20, 50, 100],
            onChangePage: function (currentPage) {
                _this.setState({ "page": currentPage }, _this.updateDataTable)
            },
            onColumnSortChange: function (changedColumn, direction) {
              const sortColumns = _this.state.sortColumns ?? _this.state.titles;
              const index = sortColumns.indexOf(changedColumn);
              if (index > -1) {
                console.log(direction)
                const sortDir = direction === 'desc' ? -1 : 1;
                _this.setState({
                  "sortValue": sortDir,
                  "sortKey": _this.state.keys[index],
                }, _this.updateDataTable)
              }
            },
            onChangeRowsPerPage: function (numberOfRows) {
              console.log("Hello World")
                _this.setState({ "limit": numberOfRows }, _this.updateDataTable)
            },
            onRowClick: function (rowData, rowMeta) {
                // rowData: string[], rowMeta: { dataIndex: number, rowIndex: number }}
            },
            onFilterChange: function (changedColumn, filterList, type, changedColumnIndex, displayData) {
                _this.setState({ filterList: filterList })
            },
            onFilterDialogClose: function () {
                if (_this.state.filterList.length === _this.columns.length) {
                    let filterObj = [];
                    for (let i = 0; i < _this.columns.length; i++) {
                        let item = _this.columns[i];
                        if (item.options.filter) {
                            let data = _this.state.filterList[i];
                            if (data.length === 1) {
                                let obj = {
                                    key: item.name.replace(/ /g, '')
                                        .toLowerCase(),
                                    value: data[0]
                                }
                                filterObj.push(obj)
                            }
                        }
                    }
                    if (filterObj.length > 0) {
                        _this.setState({ filterObj: filterObj }, _this.updateDataTable)
                    }
                }
            },
            onSearchChange: function (searchText) {
                _this.setState({
                    "search": searchText,
                    "page": 0
                }, _this.handleSearch)

            },
            customToolbar: () => {
                return (
                    <>
                        {/*<AddButton this={this}/>*/}
                        {/*<EditButton this={this}/>*/}
                        {/*<RefreshButton this={this}/>*/}
                    </>
                );
            },

            setTableProps: () => {
                return {
                    padding: 'none',
                    size: 'small',
                };
            },
        };

        this.columns = []
        this.columns.unshift(this.idColumn, this.codeColumn);
        this.state.titles.map((title, index)=> {
            let item = {
                name: title,
                options: {
                    filter: true,
                    searchable: false,
                    sortThirdClickReset: true
                }
            }
            this.columns.push(item)
        })
        this.columns.push(this.createdByColumn, this.organisationCodeColumn, this.dateCreatedColumn,);
      if(this.props.dueDate){
        this.columns.push(this.dueDateColumn)
      }
        if(this.props.addStatus){
            this.columns.push(this.viewStatus)
        }
        if(this.props.displayActions){
            this.columns.push(this.actionButtons)
        }


    }


    componentDidMount() {
        const propsFilter=this.props.propsFilter;
        if(propsFilter!==null){
            this.setState({filterObj:propsFilter})
        }
        this.updateDataTable();
    }

    handleSearch=()=>{
        clearTimeout(this.myTimeOut)
        this.myTimeOut = setTimeout(this.updateDataTable,500)
    }

    updateDataTable =  (filterObj=null) => {
      let dataSource = this.state.dataSource;
      let search = this.state.search;
      if (search !== null) {
        search = search.trim()
      }
      if (filterObj === null) {
        filterObj = this.state.filterObj;
        this.setState({filterObj: filterObj})
      }
      if (filterObj === undefined) {
        filterObj = [];
      }
      const data = {
        "limit": this.state.limit,
        "page": this.state.page,
        "sort": {
          "key": this.state.sortKey,
          "value": this.state.sortValue
        },
        "search": search,
        "filter": filterObj,
        "organisationCode": this.props.orgCode,
      };
      console.log(data);
      return this._performFetch(dataSource, data, this.handlePaginated, dataSource);
    }
    _performFetch = (url, data, callback, ...kwargs) =>{
        apiStore.post(url, data)
            .then((response) => {
                const { data } = response;
                if (callback !== undefined) {
                    return callback(data, kwargs);
                }
                return true;
            })
            .catch((error) => this.__handleCatch(error))
    }
    handlePaginated = (data) => {
        const items = [];
        const keys = this.state.keys;
        for (let i = 0; i < data.data.length; i++) {
            const item = data.data[i];
            let obj = [];
            if (item.gid){
                obj.push(item.gid)
            } else{
                if (item.id){
                    obj.push(item.id)
                }
            }
            let code = item.code;
            if (!code){
                code = 1+data.start+i;
            }
            obj.push(code);
            for (let j = 0; j < keys.length; j++) {
                const key = keys[j];
                if (item.hasOwnProperty(key)) {
                    if (key==="dateCreated"){
                        obj.push(moment(item.dateCreated).format('MMM Do YYYY'));
                    } else if (key==="dueDate"){
                        obj.push(moment(item.dueDate).format('MMM Do YYYY'));
                    } else{
                        obj.push(item[key]);
                    }
                } else { console.log("Keys not found", key)}
            }
            obj.push(item.createdBy);
            // obj.push(item.organisationCode);
            // var
            obj.push(item.organisationCode);

            obj.push(moment(item.dateCreated).format("MMM Do YY"));

            obj.push(item.status);
            items.push(obj)
        }
        this.setState({
            data: items,
            count: data.count,
            responseData: data.data
        }, function () {
        });
    }
    __handleCatch(error) {
        console.error('This is error', error);
        let errorMessage = 'Something went wrong processing your request! Please Try Again!';
        if (error.response) {
            const { status } = error.response;
            const { data } = error.response;
            if (status === 428) {
                errorMessage = data.message;
            } else if (status === 403) {
                errorMessage = 'You are not authorised to perform this operation. Please contact system administrator for assistance.';
            } else if (status === 400) {
                try {
                    errorMessage = data.errors[0].description;
                } catch (e) {}
            }
        } else {
            errorMessage ='Something went wrong processing your request'
        }
        this.setState({
            isLoading: false,
            error: true,
            errorMessage,
        });
        setTimeout(() => {
            this.setState({
                error: false,
                isLoading: false,
                errorMessage: '',
                warning: false,
            });
        }, 7000);
    }

    handleEditClicked = item => () => {
        localStorage.setItem("rowData", item.rowData)
        this.props.history.push(`${this.state.actionUrl}/${item.rowData[0]}`)
    };


    handleViewClicked = item => () => {
        return undefined
    };

    editTable = () => {
        return this.funcs.editTable();
    };

    getCreateForm=()=>{

    }
    render() {
        let { options } = this;
        options['count'] = this.state.count;
        options['rowsPerPage'] = this.state.limit;
        options['page'] = this.state.page;
        options['searchText'] = this.state.search;

        const {
            data,
            title
        } = this.state;
        const { classes } = this.props;
        return (
            <div className="page-content">
                <ThemeProvider theme={createTheme()}>
                    <MUIDataTable
                        title={title}
                        data={data}
                        columns={this.columns}
                        options={options}
                    />
                    {this.getCreateForm()}
                </ThemeProvider>
            </div>
        );
    }
}

MyTable.propTypes = {
  title: PropTypes.string,
  dataSource: PropTypes.string.isRequired,
  actionUrl: PropTypes.string.isRequired,
  keys: PropTypes.array.isRequired,
  numberFields: PropTypes.array,
  dateFields: PropTypes.array,
  titles: PropTypes.array.isRequired,
  displayActions: PropTypes.bool.isRequired,
  addStatus: PropTypes.number,
  dueDate: PropTypes.bool,
  filterObj: PropTypes.array,
  sortKey: PropTypes.string,
  sortValue: PropTypes.number
};

export default MyTable ;
