import React, { Component } from 'react';
import {Link, useHistory} from 'react-router-dom';
import { Dropdown, NavLink } from 'react-bootstrap';
import Scrollbar from 'react-perfect-scrollbar';

import logosmdark from '../../assets/img/logo-sm-dark.png';
import people5 from '../../assets/img/people/people-5.jpg';
import people9 from '../../assets/img/people/people-9.jpg';
import people3 from '../../assets/img/people/people-3.jpg';
import logo from '../../assets/img/logo.svg'
import {Services} from "../../Services";

const Navbar =() => {

    const history = useHistory();
    const services = new Services(this)
    const handleLogout=()=>{
        services.logout();
    }
    const user={
        name:localStorage.getItem('name'),
        email:localStorage.getItem('email'),
        image:localStorage.getItem('image'),
    }
    const navToggle = () => {
        document.getElementById('body').classList.toggle('ms-aside-left-open');
        document.getElementById('ms-side-nav').classList.toggle('ms-aside-open');
        document.getElementById('overlayleft').classList.toggle('d-block');
    }
  const  activityToggle = () => {
        document.getElementById('ms-recent-activity').classList.toggle('ms-aside-open');
        document.getElementById('overlayright').classList.toggle('d-block');
    }
   const optionsToggle = () => {
        document.getElementById('ms-nav-options').classList.toggle('ms-slide-down');
    }
        return (
            <nav className="navbar ms-navbar">
                <div className="ms-aside-toggler ms-toggler pl-0" data-target="#ms-side-nav" data-toggle="slideLeft" onClick={navToggle}>
                    <span className="ms-toggler-bar bg-primary" />
                    <span className="ms-toggler-bar bg-primary" />
                    <span className="ms-toggler-bar bg-primary" />
                </div>
                <div className="logo-sn logo-sm ms-d-block-sm">
                    <Link className="pl-0 ml-0 text-center navbar-brand mr-0" to="/"><img src={logosmdark} alt="logo" /> </Link>
                </div>
                <ul className="ms-nav-list ms-inline mb-0" id="ms-nav-options">
                    <li className="ms-nav-item ms-search-form pb-0 py-0">
                        <form className="ms-form" method="post">
                            <div className="ms-form-group my-0 mb-0 has-icon fs-14">
                                <input type="search" className="ms-form-input" name="search" placeholder="Search here..." />
                                <i className="flaticon-search text-disabled" />
                            </div>
                        </form>
                    </li>

                    <Dropdown className="ms-nav-item">
                        <Dropdown.Toggle as={NavLink} className="text-disabled ms-has-notification p-0" id="notificationDropdown" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false"><i className="flaticon-bell" /></Dropdown.Toggle>
                        <Dropdown.Menu className="dropdown-menu-right" aria-labelledby="notificationDropdown">
                            <li className="dropdown-menu-header">
                                <h6 className="dropdown-header ms-inline m-0"><span className="text-disabled">Notifications</span></h6><span className="badge badge-pill badge-info">4 New</span>
                            </li>
                            <li className="dropdown-divider" />
                            <Scrollbar className="ms-scrollable ms-dropdown-list">
                                <Link className="media p-2" to="#">
                                    <div className="media-body">
                                        <span>12 ways to improve your crypto dashboard</span>
                                        <p className="fs-10 my-1 text-disabled"><i className="material-icons">access_time</i> 30 seconds ago</p>
                                    </div>
                                </Link>
                                <Link className="media p-2" to="#">
                                    <div className="media-body">
                                        <span>You have newly registered users</span>
                                        <p className="fs-10 my-1 text-disabled"><i className="material-icons">access_time</i> 45 minutes ago</p>
                                    </div>
                                </Link>
                                <Link className="media p-2" to="#">
                                    <div className="media-body">
                                        <span>Your account was logged in from an unauthorized IP</span>
                                        <p className="fs-10 my-1 text-disabled"><i className="material-icons">access_time</i> 2 hours ago</p>
                                    </div>
                                </Link>
                                <Link className="media p-2" to="#">
                                    <div className="media-body">
                                        <span>An application form has been submitted</span>
                                        <p className="fs-10 my-1 text-disabled"><i className="material-icons">access_time</i> 1 day ago</p>
                                    </div>
                                </Link>
                            </Scrollbar>
                            <li className="dropdown-divider" />
                            <li className="dropdown-menu-footer text-center">
                                <Link to="#">View all Notifications</Link>
                            </li>
                        </Dropdown.Menu>
                    </Dropdown>

                    <Dropdown className="ms-nav-item ms-nav-user">
                        <Dropdown.Toggle as={NavLink} id="userDropdown" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false" className="p-0 toggle-icon-none"> <img className="ms-user-img ms-img-round float-right" src={user.image!='null'?user.image:logo} alt="people" /> </Dropdown.Toggle>
                        <Dropdown.Menu className="dropdown-menu-right user-dropdown" aria-labelledby="userDropdown">
                            <li className="dropdown-menu-header">
                                <h6 className="dropdown-header ms-inline m-0 pt-2 pb-2 pl-4"><span className="text-disabled">Welcome, {user.name}</span></h6>
                                <p className="ms-inline m-0 pt-2 pb-2 pl-4 fs-12 m-0 text-center"><span className="text-disabled">{user.email}</span></p>
                            </li>
                            <li className="dropdown-divider" />
                            <li className="ms-dropdown-list">
                                <Link className="media fs-14 pt-2 pb-2 pl-4" to="/prebuilt-pages/user-profile"> <span><i className="fa fa-user" /> My Profile</span> </Link>
                            </li>
                            <li className="dropdown-divider" />
                            <li className="dropdown-menu-footer">
                                <Link className="media fs-14 pt-2 pb-2 pl-4" to="#" onClick={()=>{handleLogout()}} > <span><i className="fa fa-power-off" /> Logout</span> </Link>
                            </li>
                        </Dropdown.Menu>
                    </Dropdown>
                </ul>
                <div className="ms-toggler ms-d-block-sm pr-0 ms-nav-toggler" data-toggle="slideDown" data-target="#ms-nav-options" onClick={optionsToggle}>
                    <span className="ms-toggler-bar bg-primary" />
                    <span className="ms-toggler-bar bg-primary" />
                    <span className="ms-toggler-bar bg-primary" />
                </div>
            </nav>
        );
    }


export default Navbar;
