import React, {useEffect, useState} from 'react';
import {Button, Modal,} from "react-bootstrap";
import {useForm, useWatch} from "react-hook-form";
import swal from "sweetalert";
import {Services} from "../../../../Services";
import {Autocomplete} from "@mui/material";
import TextField from "@mui/material/TextField";
import {AutoComplete, Select} from "antd";


const CreateDelivery=({show, onHide, products,product,org})=>{
  const services = new Services(this)
  const { register,control, handleSubmit,formState: { errors } } = useForm();
  const [selectedProduct, setSelectedProduct]=useState({});
  const [selected,setSelected]=useState([]);
  const [selectedOrg, setSelectedOrg]=useState({});
  const [locations,setLocations]=useState([]);
  const productCode =useWatch({
    control,
    name:"productCode",
    defaultValue:null
  })
  // const organisationCode =useWatch({
  //   control,
  //   name:"organisationCode",
  //   defaultValue:null
  // })
  const [options, setOptions] = useState([]);
  const [organisationCode,setOrganisationCode]=useState("");
  const searchRes=async(organisationSelect)=>{
    try {
      let orgs=[];
      (organisationSelect.data.data||[]).map(item=>{
        item.value=item.name;
        item.label=item.name;
        orgs.push(item);
      })
      return orgs
    }catch(err) {
      console.log(err)
    }
  }
  const onSearch = async (searchText) => {
    const searchOrganisations= await services.getPaginated("organisations",searchText,0,[]);
    const namesArr=await searchRes(searchOrganisations);
    try {
      setOptions(namesArr);
    }catch(err){
      console.log(err);
    }
  };
  const onSelect = (selectedName) => {
    for (let i = 0; i< options.length; i++){
      let o = options[i];
      if(o.name===selectedName) {
        setSelectedOrg(o);
        setOrganisationCode(o.code);
      }
    }
  };
  const handleChange=(values)=> {
    setSelected(values);
  }
  useEffect(()=>{
    services.getPaginated('locations','',0,[{
      "key":"organisationCode",
      "value":organisationCode
    }])
      .then((res)=>{
        setLocations(res.data.data)
      }).catch((err)=>{
      console.warn(err);
    })
  },[organisationCode]);
  useEffect(()=>{
    for (let i = 0; i< products.length; i++){
      let p = products[i];
      if (p.code===productCode){
        setSelectedProduct(p)
      }
    }
  },[productCode])
  useEffect(()=>{
    for (let i = 0; i< org.length; i++){
      let o = org[i];
      if (o.code===organisationCode){
        setSelectedOrg(o)
      }
    }
  },[organisationCode])
const title=(<span>Content</span>)

  const onSubmit=(values)=>{
    onHide();
    swal({
      title: "Create Delivery?",
      icon: "success",
      //@ts-ignore
      buttons: true,
      dangerMode: true,
    })
      .then((willDelete) => {
        if (willDelete) {
          let x=values;
          x.organisationCode=selectedOrg.code;
          x.productImage = product? product.productImage:selectedProduct.image;
          x.productName = product? product.name:selectedProduct.name;
          x.description = product? product.description:selectedProduct.description;
          x.productCode=product?product.productCode:values.productCode;
          x.quantity=product?product.quantity:values.quantity;
          x.unitPrice=product?product.unitPrice:selectedProduct.unitPrice;
          x.status="NEW";
          x.organisationName=selectedOrg.name

          services.addItem('delivery',x)
            .then((resp)=>{
              swal({
                title: "Delivery Created Successfully",
                icon: 'success',
                text:'Ask the client to confirm delivery'
              }).then(()=>'');
            })
        } else {
          swal("Delivery not created", {
            icon: "info",
          }).then(()=>'');
        }
      });
  };
  return(
    <>
      <Modal
        show={show}
        onHide={onHide}
        aria-labelledby={`contained-modal-title-vcenter`}
        centered
      >
        <Modal.Header closeButton className={`bg-success`}>
          <Modal.Title>Create Delivery</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <form onSubmit={handleSubmit(onSubmit)}>
            {product?null:
              <div className="form-group">
                <label htmlFor="organisationCode">Organisation</label>
                <AutoComplete
                  options={options}
                  style={{ width: 200 }}
                  onSelect={onSelect}
                  onSearch={onSearch}
                  className="b-block w-100"
                  id="organisationCode"
                  placeholder="search organisation"
                />
              </div>
            }
            <div className="form-group">
              <label htmlFor="location">Select Location</label>
              <select
                {...register("location", {required: true})}
                className="form-control"
                id="location"
                defaultValue={""} // Use defaultValue to set the initial value
              >
                <option value={""} disabled hidden>
                  Select Organisation Location
                </option>
                {(locations || []).map((loc, index) => (
                  <option value={loc.name} key={index}>
                    {loc.name}
                  </option>
                ))}
              </select>

              <p
                className={"error text-danger"}>{errors.location?.type === 'required' && "*REQUIRED!! Please Select Location"}</p>
            </div>
            <div className="form-group">
              <label htmlFor="openingMeter">Opening Meter</label>
              <input type="text"  {...register("openingMeter", {required: true})} className="form-control"
                     id="openingMeter" placeholder="Enter Opening Meter" />
              <p className={"error text-danger"}>{errors.openingMeter?.type === 'required' && "*REQUIRED!! Please enter Opening Meter"}</p>

            </div>
            <div className="form-group">
              <label htmlFor="closingMeter">Closing Meter</label>
              <input type="text"  {...register("closingMeter",{required:true})} className="form-control" id="closingMeter" placeholder="Enter Opening Meter" />
              <p className={"error text-danger"}>{errors.closingMeter?.type === 'required' && "*REQUIRED!! Please enter Closing Meter"}</p>
            </div>
            {product?null:
              <div className="form-group">
                <label htmlFor="productCode">Select Product</label>
                <select type="select" {...register("productCode",{required:true})}
                        className="form-control" id="productCode" defaultValue={""}>
                  <option value={""} disabled hidden>Select Product</option>

                  {(products||[]).map((product,index) =>
                    <option value={product.code} key={index}>{product.name} </option>
                  )}
                </select>
                <p className={"error text-danger"}>{errors.productCode?.type === 'required' && "*REQUIRED!! Please select the Product delivered"}</p>
              </div>
            }
            <div className="form-group">
              <label htmlFor="deliveredBy">Delivered by</label>
              <input type="text"  {...register("deliveredBy",{required:true})} className="form-control" id="deliveredBy" placeholder="Delivery Personnel" />
              <p className={"error text-danger"}>{errors.deliveredBy?.type === 'required' && "*REQUIRED!! Please enter delivery Personnel"}</p>

            </div>
            <div className="form-group">
              <label htmlFor="receivedBy">Received by</label>
              <input type="text"  {...register("receivedBy",{required:true})} className="form-control" id="receivedBy" placeholder="Received By?" />
              <p className={"error text-danger"}>{errors.receivedBy?.type === 'required' && "*REQUIRED!! Please enter a recipient"}</p>
            </div>
            {product?null:
              <>
                <div className="form-group">
                  <label htmlFor="quantity">Quantity</label>
                  <input type="number"  {...register("quantity",{required:true})} className="form-control" id="quantity" placeholder="Enter Quantity" />
                  <p className={"error text-danger"}>{errors.quantity?.type === 'required' && "*REQUIRED!! Please Enter delivery Quantity"}</p>
                </div>
              </>
            }
            <div className="form-group">
              <label htmlFor="witnessedBy">Witnessed By</label>
              <input type="text"  {...register("witnessedBy",{required:true})} className="form-control" id="witnessedBy" placeholder="Enter witness" />
              <p className={"error text-danger"}>{errors.witnessedBy?.type === 'required' && "*REQUIRED!! Please Enter a witness"}</p>
            </div>
            <div className="form-group">
              <label htmlFor="mode">Delivery Mode</label>
              <input type="text"  {...register("mode",{required:true})}className="form-control" id="mode" placeholder="Enter Delivery Mode" />
              <p className={"error text-danger"}>{errors.mode?.type === 'required' && "*REQUIRED!! Please Enter delivery Mode"}</p>
            </div>
            <div className="form-group">
              <label htmlFor="truck">Delivery Truck</label>
              <input type="text"  {...register("truck",{required:true})}className="form-control" id="truck" placeholder="Enter truck Plates" />
              <p className={"error text-danger"}>{errors.truck?.type === 'required' && "*REQUIRED!! Please Enter truck Number"}</p>
            </div>
            <div >
              <Button variant={`success`} type={`submit`}>
                <i className={`fa fa-plus`}/><span className={`text-light`}> Create Delivery</span>
              </Button>
            </div>
          </form>
        </Modal.Body>
      </Modal>
      </>
  )
}
export default CreateDelivery;
