import React, {Fragment} from 'react';
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Link} from "react-router-dom";
import 'antd/dist/antd.css';
import {Services} from "../../../../Services";
import {Form, Input, Tabs, Upload} from 'antd';

import DataTable from "../../../tables/DataTable";
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {faInbox} from "@fortawesome/free-solid-svg-icons";
import {Button, Card, Col, Row} from "react-bootstrap";
const { TextArea } = Input;
const {TabPane} = Tabs;

export default class ViewProduct extends React.Component{

    constructor(props) {
        super(props);
        this.state={
            row:props.match.params,
            product:{},
            form :{
                size:'middle',
                labelAlign:'left',
                labelCol: {

                    lg: {
                        span: 4
                    },
                    md: {
                        span: 4
                    }
                },

                wrapperCol: {
                    lg: {
                        span: 24,
                    },
                    md: {
                        span: 14
                    }
                }
            },
        }
        this.services= new Services(this);
    }
    uploadPic = (e) => {
        console.log('Upload event:', e);

        if (Array.isArray(e)) {
            return e;
        }

        return e && e.fileList;
    };
    getProduct=()=>{
        this.services.getItem('product',this.state.row.id)
            .then((res)=>{
                this.setState({
                  product:res.data,
                  unitPrice: res.data.unitPrice,
                  description: res.data.description,
                  name: res.data.name,
                  id: res.data.id,
                },()=>{
                    //this.getOrderItems(this.state.row.id);
                })
            }).catch((err)=>{
        }).catch((err) => {
            console.warn(err);
        });
    }
    onFinish = (values) => {
        let obj = {
          ...this.state.product,
          unitPrice: values.unitPrice,
          description: values.description,
          name: values.name,
          id: values.id,
        }
      this.services.editItem('product',this.state.row.id).then(res=>{
        this.services.onAddSuccess(res.data)
      }).catch(err=>{
        this.services.onAddFailed()
      })
    };

    editOrg=()=>{

        return(
            <>
                <Form {...this.state.form}
                      name="editProduct"
                      initialValues={{
                        "name":"de"
                      }}
                      onFinish={this.onFinish}>

                    <Form.Item name='name' label="Name" >
                        <Input value={this.state.name}/>
                    </Form.Item>
                    <Form.Item  name='description' label="Description"  >
                        <TextArea row={5} value={this.state.description} />
                    </Form.Item>
                    <Form.Item name='oilPrice' label="Unit Price" >
                        <Input value={this.state.unitPrice}/>
                    </Form.Item>

                    {/*<Form.Item label="Logo">
                        <Form.Item name="image" valuePropName="fileList" getValueFromEvent={this.uploadPic} noStyle>
                            <Upload.Dragger name="files" action=''>
                                <p style={{fontSize:'3.5rem', margin:'0 auto'}}>
                                    <FontAwesomeIcon color='#0054d1'  icon={faInbox}/>
                                </p>
                                <p className="ant-upload-text">Click or drag to upload</p>
                                <p className="ant-upload-hint">Add a Logo if it doesnt exist</p>
                            </Upload.Dragger>
                        </Form.Item>
                    </Form.Item>*/}

                    <Form.Item style={{textAlign:'right'}}
                               wrapperCol={{
                                   span: 24,
                               }}

                    >
                        <button style={{width:'50%',margin:'0 auto'}} type="submit" className={`btn btn-primary `}>
                            Save Details
                        </button>
                    </Form.Item>
                </Form>

            </>

        )
    }
    componentDidMount() {
        this.getProduct();
    }
    sleep = (time) => {
        return new Promise((resolve) => setTimeout(resolve, time));
    }
    jss={
        vUserTabs: {
            marginTop: '60px',
            tabsPane: {
                color: '#00897B',
                fontWeight: 600,
                marginTop: 40,
                tab: {
                    padding: '5px 10px',
                    borderRadius: '5px',
                    fontWeight: 600,
                    backgroundColor: '#f3f3f9',
                    margin: 0,
                    action:{
                        padding: '5px 10px',
                        borderRadius: '5px',
                        fontWeight: 600,
                        backgroundColor: '#007bff',
                        margin: 0,
                        color: '#fff',
                    }
                }

            },
            tabContent: {
                padding: '10px 20px',
                backgroundColor: 'transparent',
                borderRadius: '10px',
            }

        }
    }

    render() {
        return (
            <>
                <Fragment>
                    <MetaTags>
                        <title>Product</title>
                        <meta
                            name="description"
                            content="#"
                        />
                    </MetaTags>
                    <div className="body ms-body ms-aside-left-open ms-primary-theme"   id="body" >
                        {/*<Setting />*/}
                        <Sidenav/>
                        {/*<Recentactivity/>*/}
                        <main className="body-content">
                            <Navbar/>
                            <div className="ms-content-wrapper">
                                <div className="row">
                                    <div className="col-md-12">
                                        <nav aria-label="breadcrumb">
                                            <ol className="breadcrumb pl-0">
                                                <li className="breadcrumb-item"><Link to="/"><i className="bx bxs-home"/> Home</Link></li>
                                                <li className="breadcrumb-item" aria-current="page"><Link to='/products'> <i className="fa fa-box-open"/>Product</Link></li>
                                                <li className="breadcrumb-item active" aria-current="page">{this.state.row.id}</li>
                                            </ol>
                                        </nav>
                                    </div>
                                </div>
                                <div>
                                    <Card>
                                        <Card.Body>
                                            <Row>
                                                <Col md={2}>
                                                    <img
                                                        src={this.state.image}
                                                        alt={this.state.name}
                                                        style={{
                                                            width:200,
                                                            borderRadius:'20px',
                                                        }}/>
                                                </Col>
                                                <Col>
                                                    <p>Name:<b className={`text-dark`}> {this.state.name}</b></p>
                                                    <p>Description:<b className={`text-dark`}> {this.state.description}</b> </p>
                                                    <p>Unit Price:<b className={`text-dark`}> {this.state.unitPrice}</b></p>


                                                </Col>
                                            </Row>
                                            <Tabs
                                                tabBarStyle={this.jss.vUserTabs.tabsPane}
                                                tabPosition='top'>
                                                <TabPane tab={
                                                    <span  style={this.jss.vUserTabs.tabsPane.tab.action} >
                                                             <span style={{color:'#ffffff'}}><i className={`fa fa-edit`}/> Edit Product</span></span>

                                                } key="1">
                                                    <div  style={this.jss.vUserTabs.tabContent}>
                                                        <div style={{width:'50%'}}>
                                                            <Form {...this.state.form}
                                                                  name="editProduct"
                                                                  initialValues={{
                                                                    "name":"de"
                                                                  }}
                                                                  onFinish={this.onFinish}>

                                                              <Form.Item name='name' label="Name" >
                                                                <Input  value={this.state.name}/>
                                                              </Form.Item>
                                                              <Form.Item  name='description' label="Description"  >
                                                                <TextArea row={5} value={this.state.description} />
                                                              </Form.Item>
                                                              <Form.Item name='oilPrice' label="Unit Price" >
                                                                <Input value={2323}/>
                                                              </Form.Item>

                                                              <Form.Item style={{textAlign:'right'}}
                                                                         wrapperCol={{
                                                                           span: 24,
                                                                         }}

                                                              >
                                                                <button style={{width:'50%',margin:'0 auto'}} type="submit" className={`btn btn-primary `}>
                                                                  Save Details
                                                                </button>
                                                              </Form.Item>
                                                            </Form>

                                                        </div>
                                                    </div>
                                                </TabPane>
                                            </Tabs>
                                        </Card.Body>
                                    </Card>
                                </div>
                            </div>
                        </main>
                        {/*<Quickbar/>*/}
                    </div>
                </Fragment>
            </>
        )    }

}

