import React, {Fragment, useState} from "react";
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Button, Form, Row, Col, Input, Modal} from "antd";
import {Link} from "react-router-dom";
import {Card} from 'react-bootstrap';
import {Services} from "../../../../Services";
import moment from "moment";
import 'antd/dist/antd.css';
import swal from "sweetalert";
import taamLogo from '../../../../assets/img/logo.svg'
export default class ViewOrder extends React.Component{

    constructor(props) {
        super(props);
        this.state={
            row:props.match.params,
            delivery:{},
            product:{},
            customer:{},
            notes:'Taam Petroleum Thanks you For the Continued Support. ' +
                'We Pride ourselves in offering you the best Service and Products in the ' +
                'region and that is why we value our customers like you, daniel, for enabling us.',
            show:false,

        }
        this.services=new Services(this);
    }

    onHideModal=()=>{
        this.setState({show:false})
    }
    onshowModal=()=>{
        this.setState({show:true})
    }

     onSubmit=(values)=>{
        swal({
            title: "Create Invoice?",
            text: "Make sure all the data you filled in is correct",
            icon: "warning",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        }).then((willDelete) => {
            if (willDelete) {
                this.services.addItem('invoice-item',values).then(()=>{
                    swal("Invoice send successfully",{
                        icon:'success',
                    }).then(()=>'')
                })
            } else {
                swal("Invoice not added", {
                    icon: "info",
                }).then(()=>'');
            }
        });
        this.onHideModal();
    }
    getDelivery=()=>{
        this.services.getItem('delivery',this.state.row.id)
            .then((res)=>{
                this.setState({delivery:res.data},()=> '')
            })
            .then(()=>{

                this.getDeliveryItems();
            })
            .catch((err) => {
            console.warn(err);
            });
    }
    getCustomer=()=>{
        this.services.getItem('application-user',this.state.delivery.createdBy)
            .then((res)=>{
                this.setState({customer:res.data},()=>'')
            }).catch((err) => {
            console.warn(err);
        });
    }
    getDeliveryItems=()=>{
        this.services.getItem('product',this.state.delivery.productCode)
            .then((res)=>{
                this.setState({product:res.data})
            })
            .then(()=>{
                this.getCustomer();
            })
            .catch((err) => {
            console.warn(err);
        });
    }



    componentDidMount() {
        this.getDelivery();
    }

    render() {
        const {delivery,product,customer,notes}=this.state;
        return (
            <Fragment>
                <MetaTags>
                    <title>Taam | Users</title>
                    <meta
                        name="description"
                        content="#"
                    />
                </MetaTags>
                <div className="body ms-body ms-aside-left-open ms-primary-theme"   id="body" >
                    {/*<Setting />*/}
                    <Sidenav/>
                    {/*<Recentactivity/>*/}
                    <main className="body-content">
                        <Navbar/>
                        <div className="ms-content-wrapper">
                            <div className="row">
                                <div className="col-md-12">
                                    <nav aria-label="breadcrumb">
                                        <ol className="breadcrumb pl-0">
                                            <li className="breadcrumb-item"><Link to="/"><i className="bx bxs-home"/> Home</Link></li>
                                            <li className="breadcrumb-item" aria-current="page"><Link to='/deliveries'> <i className="fa fa-truck-loading"/> Deliveries</Link></li>
                                            <li className="breadcrumb-item active" aria-current="page">{this.state.row.id}</li>
                                        </ol>
                                    </nav>
                                </div>
                            </div>
                            <div>
                                <Row>
                                    <Col>
                                        <Card>
                                            <Card.Body>
                                                <Row>
                                                    <Col md={3}>
                                                        <img style={{width:100, borderRadius:'10px'}} alt={'Delivery'} src={taamLogo}/>
                                                    </Col>

                                                    <Col md={14}  className={`text-left`}>
                                                        <p><b>Hello, {customer.name}</b></p>
                                                        <p>{notes}</p>
                                                    </Col>

                                                </Row>

                                                <Row style={{
                                                    borderBottom:'1px solid #e3e3e3',
                                                    margin: '10px 0 50px'
                                                }}/>
                                                <Row>
                                                    <Col>
                                                        <h4>{product.name?product.name:''}</h4>
                                                    </Col>
                                                </Row>
                                                <Row>
                                                    <Col md={6}>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-map-marker-alt"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                               Location:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                width:'150px',
                                                                display:'inline-block',
                                                                textAlign:'left'}}
                                                            >
                                                               <b>{delivery.location}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-user-astronaut"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                               Delivered By:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                width:'150px',
                                                                display:'inline-block',
                                                                textAlign:'left'}}
                                                            >
                                                               <b>{delivery.deliveredBy}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-truck-pickup"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Mode:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                width:'150px',
                                                                display:'inline-block',
                                                                textAlign:'left'}}
                                                            >
                                                               <b>{delivery.mode}</b>
                                                            </span>
                                                        </p>
                                                    </Col>
                                                    <Col md={6}>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-user-astronaut"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Received By:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{delivery.receivedBy}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-dollar-sign"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Unit Price:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{delivery.unitPrice}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-box-open"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Quantity:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{delivery.quantity}</b>
                                                            </span>
                                                        </p>
                                                    </Col>
                                                    <Col md={6}>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-calendar-alt"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Ordered On :
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{moment(delivery.dateCreated).format("MMM Do YY")}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-clock"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Dispatched on:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{moment(delivery.timeDispatched).format("MMM Do YY h:mm a")}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-clock"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Delivered on:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{moment(delivery.timeDelivered).format("MMM Do YY h:mm a")}</b>
                                                            </span>
                                                        </p>
                                                    </Col>

                                                    <Col md={6}>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-truck"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Plate:
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{delivery.truck}</b>
                                                            </span>
                                                        </p>
                                                        <p style={{margin:0}}>
                                                            <span style={{
                                                                width:'20px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                <i className="fa fa-user-shield"/>
                                                            </span>
                                                            <span style={{
                                                                width:'100px',
                                                                display:'inline-block',
                                                                textAlign:'left'}} >
                                                                Witness :
                                                            </span>
                                                            <span
                                                                className={`text-dark`}
                                                                style={{
                                                                    width:'150px',
                                                                    display:'inline-block',
                                                                    textAlign:'left'}}
                                                            >
                                                               <b>{delivery.witnessedBy}</b>
                                                            </span>
                                                        </p>

                                                        {/*<Button onClick={()=>{*/}
                                                        {/*    this.handleDelete()*/}
                                                        {/*}} className={`btn btn-danger`}><i className={`fa fa-trash`}/> Delete Delivery</Button>*/}
                                                    </Col>

                                                </Row>


                                            </Card.Body>
                                            <Card.Footer>
                                                <Row>
                                                    <Col md={16}>
                                                        <h6 className="text-muted">Notes:</h6>
                                                        <span className=" text-justify">
                                                                All accounts are to be paid within 7 days from receipt of invoice. To be
                                                                paid by cheque or credit card or direct payment online. If account is not
                                                                paid within 7 days the credits details supplied as confirmation of work
                                                                undertaken will be charged the agreed quoted fee noted above.
                                                            </span>

                                                    </Col>
                                                    <Col md={8} className={`text-right printButton`}>
                                                        {/*<button className="btn m-2 btn-primary waves-effect waves-light me-1" onClick={this.onshowModal} ><i className="fa fa-receipt "></i> send invoice</button>*/}

                                                        <button
                                                            className="btn m-2 btn-primary waves-effect waves-light me-1"
                                                            onClick={(e) => {
                                                                window.print();
                                                            }}
                                                        >
                                                            <i className="fa fa-print "></i> Print
                                                        </button>
                                                    </Col>
                                                </Row>
                                            </Card.Footer>
                                        </Card>
                                    </Col>
                                </Row>
                            </div>
                        </div>
                    </main>
                    {/*<Quickbar/>*/}
                </div>

                <Modal
                      visible={this.state.show}
                    footer={null}
                    onCancel={this.onHideModal}
                      title={`Send Invoice`}
                >
                    <Row >
                        <Col span={24}>
                            <Form
                                labelCol={{
                                    span: 8,
                                }}
                                wrapperCol={{
                                    span: 16,
                                }}
                                // initialValues={{
                                //     remember: true,
                                // }}
                                onFinish={this.onSubmit}
                                autoComplete="off"
                            >

                                <Form.Item
                                    name="organisationCode"
                                    label={"Org. Code"}
                                >
                                    <Input readOnly autoComplete="off" defaultValue={delivery.organisationCode}  />
                                </Form.Item>
                                <Form.Item
                                    name="description"
                                    label={"Description"}
                                    rules={[
                                        {
                                            required: true,
                                            message:""
                                        },
                                    ]}
                                >
                                    <Input type="text"   placeholder="Description" />
                                </Form.Item>
                                <Form.Item
                                    name="status"
                                    hidden={true}
                                >
                                    <Input type="text" defaultValue="PENDING"   />
                                </Form.Item>
                                <Form.Item
                                    name="about"
                                    label="Total Amount"
                                >
                                    <Input
                                        defaultValue={delivery.unitPrice * delivery.quantity}
                                         />
                                </Form.Item>
                                <Button style={{float:"right", colo:'#FFFFFF'}} type="primary" className={`btn btn-primary text-light p-0`}  htmlType="submit">
                                    <span style={{color:'#FFFFFF'}}>Send</span>
                                </Button><br/>
                            </Form>
                        </Col>
                    </Row>
                </Modal>
            </Fragment>
        )
    }
    jss={
        vUserTabs: {
            marginTop: '60px',
            tabsPane: {
                color: '#00897B',
                fontWeight: 600,
                marginTop: 40,
                tab: {
                    padding: '5px 10px',
                    borderRadius: '5px',
                    fontWeight: 600,
                    backgroundColor: '#f3f3f9',
                    margin: 0
                }

            },
            tabContent: {
                padding: '10px 20px',
                backgroundColor: 'transparent',
                borderRadius: '10px',
            }

        }
    }

    handleDelete=()=> {
        swal({
            title: "Delete delivery?",
            text: "Once you delete an delivery, You cannot retrieve it!",
            icon: "warning",
            buttons: true,
            dangerMode: true,
        })
            .then((willDelete) => {
                if (willDelete) {

                    this.services.deleteItem('delivery',this.state.row.id).then(()=>{
                        swal("delivery Successfully Deleted", {
                            icon: "info",
                        }).then(()=> {
                            this.props.history.push('/deliveries')
                        });

                    })

                } else {
                    // @ts-ignore
                    swal.close()
                }
            });
    }

    handleAdd(code) {


    }
}
