import React, {Fragment, useEffect} from "react";
import MetaTags from "react-meta-tags";
import Sidenav from "../../../layouts/Sidenav";
import Recentactivity from "../../../layouts/Recentactivity";
import Navbar from "../../../layouts/Navbar";
import {Select, Tabs} from "antd";
import {Link} from "react-router-dom";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEnvelope, faEnvelopeOpenText, faInbox, faPhone, faPhoneSquare, faUserCircle, faUserLock } from '@fortawesome/free-solid-svg-icons';
import 'antd/dist/antd.css';
import userAvt from '../../../../assets/img/avt.svg'
import 'bootstrap/dist/css/bootstrap.min.css';
import {Services} from "../../../../Services";
import {Button, Card, Col, Modal, Row} from "react-bootstrap";
import classNames from "classnames";
import moment from "moment";
import DataTable from "../../../tables/DataTable";
import {Form, Input, Upload, Button as AntButton} from 'antd';
import {FaPlus, FaPlusSquare} from "react-icons/fa";
const {TabPane} =Tabs;
const { TextArea } = Input;
const { Option } = Select;

export default class ViewOrg extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      row: props.match.params,
      org: {},
      show:false,
      values:{},
      status: '',
      form: {
        size: 'middle',
        labelAlign: 'left',
        labelCol: {

          lg: {
            span: 4
          },
          md: {
            span: 4
          }
        },

        wrapperCol: {
          lg: {
            span: 24,
          },
          md: {
            span: 14
          }
        }
      },
      title: [
        'Orders',
        'Invoices',
        'Deliveries',
        'Payments',
        'Users',
        'Locations',
      ],
      dataSource: [
        'orders',
        'invoices',
        'deliveries',
        'payments',
        'application-users',
        'locations',
        'trucks',
      ],
      actionUrl: [
        'order',
        'invoice',
        'delivery',
        'payment',
        'application-user',
        'location',
        'truck',
      ],
      keys: [
        ['deliveryLocation', 'orderedBy', 'lpoNumber', 'status'],
        ['number', 'description', 'amount', 'status'],
        ['location', 'mode', 'truck', 'quantity', 'unitPrice', 'deliveredBy', 'receivedBy'],
        ['paidBy', 'amount', 'number', 'method', 'description', 'status', 'confirmedBy'],
        ['name', 'email', 'phoneNumber', 'role', 'organisationCode', 'status'],
        ['organisationCode', 'name', 'description'],
        ['name', 'type', 'description', 'plateNumber'],
      ],
      titles: [
        ['Delivery Location', 'Ordered By', 'Order Number', 'Status'],
        ['number', 'description', 'amount', 'status'],
        ['location', 'mode', 'truck', 'quantity', 'unit Price', 'Driver', 'Recipient'],
        ['paidBy', 'amount', 'number', 'method', 'description', 'status', 'confirmed By'],
        ['Name', 'email', 'phone Number', 'Role', 'organisation Code', 'Status'],
        ['Organisation', 'name', 'description'],
        ['Name', 'Type', 'description', 'Plate Number'],
      ],
      numberFields: [],
      dateFields: [],
      filterObj: [[{
        'key': 'organisationCode',
        'value': `${props.match.params.id}`,
      }]],
      displayActions: false,
      formData: {
      }
    }
    this.services = new Services(this);
    this.child = React.createRef();
  }

  onShow=()=> this.setState({show:true});
  onHide=()=> this.setState({show:false});


  handleChange = (event) => {
    const name = event.target.name;
    const value = event.target.value;
    console.log("values", `{${name}:${value}}`)
    let obj = JSON.parse(JSON.stringify(this.state.values))
    obj[name] = value;
    this.setState({values: obj})
  }
  onSubmit=(e)=>{
    e.preventDefault()
    console.log(this.state.values);
    let data= this.state.values;
    data["organisationCode"] = this.state.organisation.code
    this.services.addItem("location", this.state.values).then((res)=>{
      this.services.onAddSuccess(res)
      this.onHide()
    }).catch(err=>{
      console.warn(err)
      this.services.onAddFailed()
    })
  }
  getOrder = () => {
    this.services.getItem('organisation', this.state.row.id)
      .then((res) => {
        this.setState({org: res.data, organisation: res.data}, () => {
          //this.getOrderItems(this.state.row.id);
        })
      }).catch((err) => {

    }).catch((err) => {
      console.warn(err);
    });
  }

  onFinish = (values) => {
    let org = JSON.parse(JSON.stringify(this.state.organisation));
    Object.keys(values).forEach(function(key) {
      let val = values[key];
      if (val!==null && val !==undefined && val!==""){
        org[key] =val
      }
    });
    this.services.editItem('organisation', org)
      .then((res) => {
        this.services.onAddSuccess(res);
        this.getOrder();
      }).catch((err) => {
      this.services.onAddFailed();
    })
  };
  editOrg = () => {
    let {org} = this.state;
    return (
      <>
        <Form {...this.state.form}
              name="editOrganisation"
              onFinish={this.onFinish}>
          <Form.Item name='name' label="Name">
            <Input defaultValue={org.name} id="success"/>
          </Form.Item>
          <Form.Item name='description' label="Line of Business">
            <TextArea row={5} defaultValue={org.description} id="success"/>
          </Form.Item>
          <Form.Item name='oilPrice' label="Oil Price">
            <Input defaultValue={org.oilPrice} id="success"/>
          </Form.Item>
          <Form.Item name='dieselPrice' label="Diesel Price">
            <Input defaultValue={org.dieselPrice} id="dieselPrice"/>
          </Form.Item>

          <Form.Item name='petrolPrice' label="Petrol Price">
            <Input defaultValue={org.petrolPrice} id="success"/>
          </Form.Item>
          <Form.Item name='status' label="Status">
            {/*<Input defaultValue={org.status} id="status"/>*/}
            <Select id="status"placeholder={"Select Class"}>
              <Select.Option key={"ACTIVE"}>ACTIVE</Select.Option>
              <Select.Option key={"INACTIVE"}>INACTIVE</Select.Option>
            </Select>
          </Form.Item>
          <Form.Item name='physicalAddress' label="Official Physical Address">
            <Input defaultValue={org.physicalAddress} id="physicalAddress"/>
          </Form.Item>
          <Form.Item name='organisationClass' label="Organisation Class">
            <Select id="organisationClass"placeholder={"Select Class"}>
              <Select.Option key={"TIER 1"}>TIER 1</Select.Option>
              <Select.Option key={"TIER 2"}>TIER 2</Select.Option>
              <Select.Option key={"TIER 3"}>TIER 3</Select.Option>
            </Select>
          </Form.Item>
          <Form.Item name='accountManager' label="Account Manager">
            <Input defaultValue={org.adminName} id="accountManager"/>
          </Form.Item>
          <Form.Item label="Logo">
            <Form.Item name="image" valuePropName="fileList" getValueFromEvent={this.uploadPic} noStyle>
              <Upload.Dragger name="files" action='/qubeans/management/phone-blacklist/APW'>
                <p style={{fontSize: '3.5rem', margin: '0 auto'}}>
                  <FontAwesomeIcon color='#0054d1' icon={faInbox}/>
                </p>
                <p className="ant-upload-text">Click or drag to upload</p>
                <p className="ant-upload-hint">Add a Logo if it doesnt exist</p>
              </Upload.Dragger>
            </Form.Item>
          </Form.Item>

          <Form.Item style={{textAlign: 'right'}}
                     wrapperCol={{
                       span: 24,
                     }}

          >
            <Button style={{width: '50%', margin: '0 auto'}} type="primary" htmlType="submit">
              Save Details
            </Button>
          </Form.Item>
        </Form>

      </>

    )
  }

  componentDidMount() {
    this.getOrder();
  }

  render() {
    const {org} = this.state;
    return (
      <Fragment>
        <MetaTags>
          <title>Taam | Users</title>
          <meta
            name="description"
            content="#"
          />
        </MetaTags>
        <div className="body ms-body ms-aside-left-open ms-primary-theme" id="body">
          {/*<Setting />*/}
          <Sidenav/>
          {/*<Recentactivity/>*/}
          <main className="body-content">
            <Navbar/>
            <div className="ms-content-wrapper">
              <div className="row">
                <div className="col-md-12">
                  <nav aria-label="breadcrumb">
                    <ol className="breadcrumb pl-0">
                      <li className="breadcrumb-item"><Link to="/"><i
                        className="bx bxs-home"/> Home</Link></li>
                      <li className="breadcrumb-item" aria-current="page"><Link to='/orgs'> <i
                        className="fa fa-building"/>Organisations</Link></li>
                      <li className="breadcrumb-item active"
                          aria-current="page">{this.state.row.id}</li>
                    </ol>
                  </nav>
                </div>
              </div>
              <div>
                <Row>
                  <Col>
                    <Card>
                      <Card.Body>
                        <Row>

                          <Col md={1}>
                            <img
                              src={org.image ? org.image : userAvt}
                              alt={org.name}
                              style={{
                                borderRadius: 100,
                                width: 100,
                                height: 100,
                                objectFit: 'cover',
                                border: '1px solid #efefef'
                              }}
                            />

                          </Col>
                          <Col md={2} style={{
                            padding: '20px 0 0'
                          }}>
                            <p style={{margin: 0}}><i
                              className={`fa fa-user-circle`}/> Name: <b>{org.name}</b>
                            </p>
                            <p style={{margin: 0}}><i className="fa fa-feather-alt"/> Line
                              of Business : <b>{org.description}</b></p>
                            <p style={{margin: 0}}>
                                                            <span><i
                                                              className="fa fa-calendar-alt"/> Created on {moment(org.dateCreated).format("MMM Do YY")}
                                                              <br/>
                                                        </span>
                            </p>


                          </Col>
                          <Col md={2} style={{
                            padding: '20px 0 0'
                          }}>

                            <p style={{margin: 0}}><i className="fa fa-oil-can"/> Oil Price
                              : <b>{org.oilPrice}</b></p>
                            <p style={{margin: 0}}><i className="fa fa-spray-can"/> Petrol
                              Price : <b>{org.petrolPrice}</b></p>
                            <p style={{margin: 0}}><i className="fa fa-tint"/> Diesel Price
                              : <b>{org.dieselPrice}</b></p>
                          </Col>
                          <Col md={2} style={{
                            padding: '20px 0 0'
                          }}>

                            <p style={{margin: 0}}><i className="fa fa-map-marked-alt"/> Physical
                              Address :
                              <b>{org.physicalAddress}</b></p>
                          </Col>


                        </Row>
                        <Tabs
                          tabBarStyle={this.jss.vUserTabs.tabsPane}
                          tabPosition='top'
                        >

                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-shopping-basket'/>
                                                                    <i> </i>Orders</span>

                          } key="1">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <DataTable title={this.state.title[0]}
                                         keys={this.state.keys[0]}
                                         actionUrl={this.state.actionUrl[0]}
                                         numberFields={this.state.numberFields[0]}
                                         dataSource={this.state.dataSource[0]}
                                         dateFields={this.state.dateFields[0]}
                                         titles={this.state.titles[0]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>
                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-truck-loading'/>
                                                                    <i> </i>Deliveries</span>

                          } key="2">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <DataTable title={this.state.title[2]}
                                         keys={this.state.keys[2]}
                                         actionUrl={this.state.actionUrl[2]}
                                         numberFields={this.state.numberFields[2]}
                                         dataSource={this.state.dataSource[2]}
                                         dateFields={this.state.dateFields[2]}
                                         titles={this.state.titles[2]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>
                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-receipt'/>
                                                                    <i> </i>Invoices</span>

                          } key="3">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <DataTable title={this.state.title[1]}
                                         keys={this.state.keys[1]}
                                         actionUrl={this.state.actionUrl[1]}
                                         numberFields={this.state.numberFields[1]}
                                         dataSource={this.state.dataSource[1]}
                                         dateFields={this.state.dateFields[1]}
                                         titles={this.state.titles[1]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>
                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-money-check-alt'/>
                                                                    <i> </i>Payments</span>

                          } key="4">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <DataTable title={this.state.title[3]}
                                         keys={this.state.keys[3]}
                                         actionUrl={this.state.actionUrl[3]}
                                         numberFields={this.state.numberFields[3]}
                                         dataSource={this.state.dataSource[3]}
                                         dateFields={this.state.dateFields[3]}
                                         titles={this.state.titles[3]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>
                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-users'/>
                                                                    <i> </i>Users</span>

                          } key="5">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <DataTable title={this.state.title[4]}
                                         keys={this.state.keys[4]}
                                         actionUrl={this.state.actionUrl[4]}
                                         numberFields={this.state.numberFields[4]}
                                         dataSource={this.state.dataSource[4]}
                                         dateFields={this.state.dateFields[4]}
                                         titles={this.state.titles[4]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>
                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab}>
                                                            <i className='fa fa-map-marker-alt'/>
                                                                    <i> </i>Locations</span>

                          } key="location">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <button onClick={()=>this.onShow()} className={"btn p-1 pl-3 pr-3 btn-primary float-right"}> <FaPlus/> Create Location</button>
                              <Modal show={this.state.show} onHide={this.onHide} backdrop="static" keyboard={false} aria-labelledby="contained-modal-title-vcenter" centered>
                                <Modal.Header className={`bg-success`} closeButton>
                                  <Modal.Title>Create Location</Modal.Title>
                                </Modal.Header>
                                <Modal.Body>
                                  <form>

                                    <div className="form-group">
                                      <label htmlFor="name">Location Name</label>
                                      <input type="text" onChange={this.handleChange}  className="form-control" name="name" placeholder={`Enter Location Name`}/>
                                    </div>
                                    <div className="form-group">
                                      <label htmlFor="description">Description</label>
                                      <input type="text" onChange={this.handleChange} className="form-control" name="description" placeholder={`Describe your location`} />
                                    </div>
                                    <div className="form-group">
                                      <label htmlFor="contactPersonName">Contact Person Name</label>
                                      <input type="text"  onChange={this.handleChange} className="form-control" name="contactPersonName" placeholder={`Enter Contact Person Name`} />
                                    </div>
                                    <div className="form-group">
                                      <label htmlFor="contactPersonEmail">Contact Person Email</label>
                                      <input type="text"  onChange={this.handleChange} className="form-control" name="contactPersonEmail" placeholder={`Enter Email Address`} />
                                    </div>
                                    <div className="form-group">
                                      <label htmlFor="contactPersonPhone">Contact Person Phone</label>
                                      <input type="text" onChange={this.handleChange} className="form-control" name="contactPersonPhone" placeholder={`Enter Phone Number`} />
                                    </div>


                                    <div>
                                      <button onClick={this.onSubmit} style={{
                                        margin:'10px 15px 30px auto',
                                      }} className={`btn btn-success`}>
                                        <i className={`fa fa-plus`}/><span style={{color:'#fff',fontWeight:600}}>Create Location</span>
                                      </button>
                                    </div>
                                  </form>
                                </Modal.Body>

                              </Modal>

                              <DataTable title={this.state.title[5]}
                                         keys={this.state.keys[5]}
                                         actionUrl={this.state.actionUrl[5]}
                                         numberFields={this.state.numberFields[5]}
                                         dataSource={this.state.dataSource[5]}
                                         dateFields={this.state.dateFields[5]}
                                         titles={this.state.titles[5]}
                                         displayActions={this.state.displayActions}
                                         filterObj={this.state.filterObj[0]}
                              />

                            </div>
                          </TabPane>

                          <TabPane tab={
                            <span style={this.jss.vUserTabs.tabsPane.tab.action}>
                                                             <span style={{color: '#ffffff'}}><i
                                                               className={`fa fa-edit`}/> Edit Organisation</span></span>

                          } key="9">
                            <div style={this.jss.vUserTabs.tabContent}>
                              <div style={{width: '50%'}}>
                                {this.editOrg()}
                              </div>
                            </div>
                          </TabPane>
                        </Tabs>

                      </Card.Body>
                    </Card>
                  </Col>
                </Row>
              </div>
            </div>
          </main>
          {/*<Quickbar/>*/}
        </div>
      </Fragment>
    )
  }

  jss = {
    vUserTabs: {
      marginTop: '60px',
      tabsPane: {
        color: '#00897B',
        fontWeight: 600,
        marginTop: 40,
        tab: {
          padding: '5px 10px',
          borderRadius: '5px',
          fontWeight: 600,
          backgroundColor: '#f3f3f9',
          margin: 0,
          action: {
            padding: '5px 10px',
            borderRadius: '5px',
            fontWeight: 600,
            backgroundColor: '#007bff',
            margin: 0,
            color: '#fff',
          }
        }

      },
      tabContent: {
        padding: '10px 20px',
        backgroundColor: 'transparent',
        borderRadius: '10px',
      }

    }
  }
}
