import React from "react";
import axios from "axios";
import swal from "sweetalert";

export const v1_base_urls = 'http://13.61.37.35/taam/v1/';
export const base_url = 'http://13.61.37.35/taam/admin/';
export class Services {
  constructor(that) {
    this.that = that;
    this.state = {
      logger: false
    }
  }

  api = () => {
    return axios.create({
      baseURL: base_url,
      headers: {
        Authorization: `Bearer ${localStorage.getItem('AuthToken')}`,
        'Access-Control-Allow-Origin': '*'
      }
    });
  }
  deleteItem = (url, code) => {
    url = url + "/" + code
    return this.api().delete(url)
  }
  login = (data) => {
    axios.post(`${v1_base_urls}login`, data).then((res) => {
      if (res.data.status === "SUCCESS") {
        localStorage.setItem('AuthToken', res.data.token);
        localStorage.setItem('name', res.data.name);
        localStorage.setItem('email', res.data.email);
        localStorage.setItem('image', res.data.image);
        localStorage.setItem('code', res.data.code);
        localStorage.setItem('organisationName', res.data.organisationName);
        localStorage.setItem('organisationCode', res.data.organisation);
        window.location.pathname = '/';
        this.that.forceUpdate();
      } else {
        swal({
          title: "Failed To Login!",
          text: `${res.data.message}`,
          icon: "error",
          position: '',
        }).then(() => '');
      }
    })
  }
  logout = () => {
    localStorage.clear();
    window.location.pathname = '/login'
    this.that.forceUpdate();
  }
  getItem = (url, code) => {
    url = url + "/" + code
    return this.api().get(url)
  }
  editItem = (url, data) => {

    return this.api().put(url, data)
  }
  addItem = (url, data) => {
    return this.api().post(url, data)
  }
  getData = (url) => {
    return this.api().post(url)
  }
  onAddSuccess = (data) => {
    swal({
      title: data.data.status,
      text: "Item Added Successfully",
      icon: "success",
    }).then(() => '');
  }
  onAddFailed = () => {
    swal({
      title: 'ERROR!',
      text: "Action Failed",
      icon: "error",
    });
  }

  onCreateSuccess = (data) => {
    const _this = this;
    swal({
      title: "Success!",
      text: "created successfully",
      icon: "success",
    }).then(() => '');
    this.updateDataTable();
    this.that.setState({
      isLoading: false,
      error: false,
      errorMessage: '',
      warning: false,
      addFormOpen: false
    })
    _this.that.child.current.funcs.refresh()
    setTimeout(() => {
      swal.close();

    }, 10);
  }
  updateModelStatus = (id, status, modelName) => {
    return this.api().post('update-model-status', {
      'id': id,
      'status': status,
      'modelName': modelName,
    })
  }

  getPaginated = (url, search, page, filter = []) => {
    if (search !== null) {
      search = search.trim()
    }
    return this.api().post(url, {
      "limit": 20,
      "page": page,
      "search": search,
      "sort": {
        "key": "",
        "value": 0
      },
      "filter": filter
    })
  }
}
