import React, {useEffect, useState} from 'react';
import Breadcrumb from './Breadcrumb';
import UpdateUser from "./UpdateUser";
import TruckList from "./TruckList";
import {Button, Col, Form, Input, Modal, Row, Select, Upload} from "antd";
import {UploadOutlined} from "@ant-design/icons";
import {Services} from "../../../../Services";
import swal from "sweetalert";
const {TextArea} = Input;

const Content =()=> {
    const[show,setShow]=useState(false);
    const [organisations, setOrganisations]=useState([]);
    const [form, setForm]=useState(
        {
            size:'middle',
            labelAlign:'left',
            layout:'vertical',
            labelCol: {

                lg: {
                    span: 6
                },
                md: {
                    span: 6
                }
            },

            wrapperCol: {
                lg: {
                    span: 24,
                },
                md: {
                    span: 24
                }
            }
        },
    );
    const onshowModal=()=>setShow(true);
    const onHideModal=()=>setShow(false);
    const services = new Services(this);

    useEffect(()=>{
        services.getPaginated('organisations', '', 0, []).then((resp) =>{
            setOrganisations(resp.data.data);

        })
    },[])
    const onSubmit=(values)=>{
        swal({
            title: "Create Fleet?",
            text: "Make sure all the data you filled in is correct",
            icon: "warning",
            //@ts-ignore
            buttons: true,
            dangerMode: true,
        }).then((willDelete) => {
            if (willDelete) {
                services.addItem('truck',values).then(()=>{
                    swal("Fleet created successfully",{
                        icon:'success',
                    }).then(()=>'')
                })
            } else {
                swal("Fleet not created", {
                    icon: "info",
                }).then(()=>'');
            }
        });
        onHideModal();
    }
        return (
            <div className="ms-content-wrapper">
                <div className="row">
                    <Breadcrumb/>
                </div>
                <div className={`row`}>
                    <button style={{margin:'10px 15px 20px auto'}} onClick={onshowModal} className={`btn btn-sm btn-primary`}>
                        <i className={`fa fa-plus`}/> Add Fleet
                    </button>
                </div>
                <TruckList/>
                <Modal
                    visible={show}
                    footer={null}
                    onCancel={onHideModal}
                    title={`Add Fleet`}
                >

                    <Row justify={"center"}>
                        <Col span={24}  ><br/>

                            <Form
                                {...form}
                                initialValues={{
                                    remember: true,
                                }}
                                onFinish={onSubmit}
                                autoComplete="off"
                            >
                                <Form.Item
                                    name="organisationCode"
                                    label="Organisation"
                                    rules={[
                                        {
                                            required: true,
                                            message:"Kindly select organisation"
                                        },
                                    ]}
                                >
                                    <Select placeholder={"Select Organisation"}>

                                        {organisations.map((org,index)=>
                                            <Select.Option key={index} value={org.organisationCode}>{org.name}</Select.Option>
                                        )}

                                    </Select>
                                </Form.Item>

                                <Form.Item
                                    name="name"
                                    label="Fleet Name"
                                    rules={[
                                        {
                                            required: true,
                                            message:""
                                        },
                                    ]}
                                >
                                    <Input autoComplete="off"  placeholder="Name" />
                                </Form.Item>
                                <Form.Item
                                    name="description"
                                    label="Description"
                                    rules={[
                                        {
                                            required: true,
                                            message:""
                                        },
                                    ]}
                                >
                                    <TextArea   placeholder="Description" />
                                </Form.Item>
                                <Form.Item
                                    name="plateNumber"
                                    label="PlateNumber"
                                    rules={[
                                        {
                                            required: true,
                                            message:""
                                        },
                                    ]}
                                >
                                    <Input
                                        type={"number"}
                                        placeholder="Plate Number" />
                                </Form.Item>
                                <Form.Item
                                    name="type"
                                    label="Type"
                                    rules={[
                                    {
                                        required: true,
                                        message:""
                                    },
                                    ]}
                                >
                                        <Select placeholder={"Fleet Type"}>
                                            <Select.Option value="Truck">Truck</Select.Option>
                                            <Select.Option value="Generator">Generator</Select.Option>
                                        </Select>
                                </Form.Item>
                                <button style={{float:"right", color:"#ffffff"}}  type="submit"  className="btn btn-primary">
                                    add Fleet
                                </button><br/>
                            </Form>
                        </Col>
                    </Row>

                </Modal>
            </div>
        );
    }
export default Content;
